INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) VALUES('atlas-tomato-gray-mold-public',1,'PUBLISHED','{"cropName":"番茄","cropAliases":["西红柿"],"diseaseName":"灰霉病","diseaseAliases":["番茄灰霉病"],"symptomKeywords":["灰霉","灰色霉层","灰绿色霉层","灰褐色霉层","水浸状","果实软腐","倒V形","叶尖"],"affectedParts":["花","果实","叶片","茎","果柄"],"growthStages":[],"identification":"公开资料描述：花、果实、叶片和茎均可受害。青果多从残留柱头或花瓣向果面、果柄扩展，果皮灰白、软腐并长灰绿色霉层；叶片多从叶尖呈倒V形向内扩展，初期水浸状、浅褐色，后可见灰霉；茎病斑可呈长形，湿度大时出现灰褐色霉层。低温高湿有利发病。","differential":"本条为来源特征整理，不含现场确诊结论。核对受害部位、霉层颜色、叶尖病斑及湿度条件；仅有黄叶或腐烂不足以判定灰霉病。其他病害、药害或缺素不能凭本条排除，证据不足时补拍、采样并交农技人员复核。","measures":"加强通风和湿度管理，浇水宜在上午，发病初期节制浇水、防止结露；及时清除病果、病叶和受害侧枝并按当地植保要求处理，减少传播。具体棚温和用药须由农技人员结合现场及当前有效登记核对，本条不导入原文药剂、剂量或安全间隔。","source":"上海市农业农村委员会 / 上海三农服务热线","sourceVersion":"2025-01-09；2026-11-14公开全文整理","sourceRef":"《番茄灰霉病如何防治？》病状、农业防治段；https://nyncw.sh.gov.cn/bwbdzzl/20250109/560a204e611b4151921fa7fb5423b859.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='atlas-tomato-gray-mold-public' AND revision=1;
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '84af8387-b43d-5ef6-802e-596844a4d5ae',1,'PUBLISHED','{"cropName":"番茄","cropAliases":["西红柿"],"diseaseName":"早疫病","diseaseAliases":["番茄早疫病"],"symptomKeywords":["同心轮纹","轮纹斑","黄色晕圈","小黑点","黑色霉层","果实开裂"],"affectedParts":["叶片","茎","叶柄","果实"],"growthStages":[],"identification":"叶片先出现针尖状小黑点，扩大为带同心轮纹的病斑，边缘可有浅绿色或黄色晕圈。茎分枝处可见褐色不规则斑及灰黑霉状物；果实多从花萼附近出现褐黑色凹陷斑，后期可开裂，病部较硬。","differential":"结合轮纹结构、受害部位和病斑质地判断，避免与灰霉、其他叶斑或生理性坏死混同。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"定植初期避免长时间闷棚，结合天气调节温湿度，记录病斑扩展并采样复核。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"上海市农业农村委员会 / 上海三农服务热线","sourceVersion":"2025-03-07；2026-11-14公开全文整理","sourceRef":"《番茄早疫病如何防治？》病状与棚室管理段；https://nyncw.sh.gov.cn/bwbdzzl/20250308/672f3428364e4f4989023060b64f0e14.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='84af8387-b43d-5ef6-802e-596844a4d5ae' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番茄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='早疫病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='84af8387-b43d-5ef6-802e-596844a4d5ae' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '3431c238-5b88-5d64-8aa8-2c585a8b8176',1,'PUBLISHED','{"cropName":"番茄","cropAliases":["西红柿"],"diseaseName":"粉虱","diseaseAliases":["番茄粉虱"],"symptomKeywords":["白色小飞虫","白色蜡粉","粉虱","叶背虫体","煤污","褪绿"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"群集在叶片背面刺吸汁液，叶片可褪绿、变黄、萎蔫，有时伴煤污。成虫虫体及翅有白色蜡粉，具有趋黄性。","differential":"黄叶或煤污不是粉虱的专有症状，须拍清叶背虫体；与蚜虫、蓟马等区分，未能观察虫体时不作虫种确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"检查并修补棚口防虫网，配合黄板监测，记录叶背虫量；低密度时由农技人员评估天敌防控。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='3431c238-5b88-5d64-8aa8-2c585a8b8176' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番茄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='粉虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='3431c238-5b88-5d64-8aa8-2c585a8b8176' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '02cf329d-e739-531f-a317-0065cfa0d167',1,'PUBLISHED','{"cropName":"番茄","cropAliases":["西红柿"],"diseaseName":"蓟马","diseaseAliases":["番茄蓟马"],"symptomKeywords":["银白色斑痕","银白斑","细长小虫","花朵褐变","落花落果","蓟马"],"affectedParts":["花","嫩梢","叶片"],"growthStages":[],"identification":"花、嫩梢、叶片可受害，叶片出现银白色斑痕，花朵可褐变、畸形，严重时落花落果。成虫微小细长，多为黄褐色或黑色，活动隐蔽。","differential":"银白斑痕应结合花内或嫩梢细长虫体观察，与螨害、擦伤或药害区分；仅凭花畸形不能确定蓟马。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"检查花、嫩梢和叶背，记录虫量和受害范围；修补防虫网，配合蓝板监测，天敌释放由农技人员评估。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='02cf329d-e739-531f-a317-0065cfa0d167' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番茄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='02cf329d-e739-531f-a317-0065cfa0d167' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '64fed43a-f1ee-57bf-827e-fca1e43da925',1,'PUBLISHED','{"cropName":"黄瓜","cropAliases":[],"diseaseName":"霜霉病","diseaseAliases":["黄瓜霜霉病"],"symptomKeywords":["黄色多角形","黄斑","角形病斑","受叶脉限制","紫灰色霉层","叶背霉层"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"叶片正面出现黄色多角形病斑，扩展受叶脉限制；湿度大时叶背相应病部可生紫灰色霉层。","differential":"需与细菌性角斑病比较：重点观察叶背霉层、是否菌脓和穿孔；同一叶片可能混合发生，不凭黄斑单独确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='64fed43a-f1ee-57bf-827e-fca1e43da925' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='黄瓜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='霜霉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='64fed43a-f1ee-57bf-827e-fca1e43da925' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '85ad8bcd-12a6-5784-a0b9-73e4d98d0e39',1,'PUBLISHED','{"cropName":"黄瓜","cropAliases":[],"diseaseName":"白粉病","diseaseAliases":["黄瓜白粉病"],"symptomKeywords":["白粉","白色粉斑","白色粉状","白色霉斑","圆形小粉斑"],"affectedParts":["叶片","叶柄","茎蔓"],"growthStages":[],"identification":"瓜类叶面或叶背先出现白色近圆形小粉斑，随后扩大并连成不规则白粉状霉斑；叶片为主要受害部位，叶柄和茎蔓次之。","differential":"注意区分附着粉尘、喷药残留和霜霉，记录白粉是否逐步扩展及其受害部位。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='85ad8bcd-12a6-5784-a0b9-73e4d98d0e39' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='黄瓜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='85ad8bcd-12a6-5784-a0b9-73e4d98d0e39' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7074c9c2-fcea-5f34-866c-eb4462222806',1,'PUBLISHED','{"cropName":"黄瓜","cropAliases":[],"diseaseName":"细菌性角斑病","diseaseAliases":["角斑病","黄瓜角斑病","黄瓜细菌性角斑病"],"symptomKeywords":["乳白色菌脓","菌脓","角形病斑","穿孔","水浸状透明","灰白色病斑"],"affectedParts":["叶片","叶背","果实","茎蔓"],"growthStages":[],"identification":"幼叶先出现水浸状透明小斑点，扩大后出现黄色晕环、淡黄至褐色斑；老叶病斑受叶脉限制呈角形。潮湿时叶背可溢出细粒状乳白色菌脓，老斑易破裂、穿孔脱落。","differential":"需与霜霉病鉴别，重点比较菌脓、破裂穿孔与紫灰霉层，混合发生时建议采样检测。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"避免连作；绑蔓、摘心和采收尽量选择叶面露水干后进行，减少湿叶作业传播，记录菌脓与穿孔特征。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"上海市农业农村委员会 / 上海三农服务热线","sourceVersion":"2014-05-15；2026-11-14公开全文整理","sourceRef":"《黄瓜叶子上有白斑，使用什么农药？》症状及加强管理段；https://nyncw.sh.gov.cn/bwbdzzl/20190104/0009-110366.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7074c9c2-fcea-5f34-866c-eb4462222806' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='黄瓜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='细菌性角斑病'));
