INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '78054ae7-dfcf-57dc-8b19-e4efae4d2d65',1,'PUBLISHED','{"cropName":"黄瓜","cropAliases":[],"diseaseName":"菌核病","diseaseAliases":["黄瓜菌核病"],"symptomKeywords":["白色棉絮","白色菌丝","黑色菌核","鼠粪状","茎蔓水渍","湿腐"],"affectedParts":["茎蔓","叶片","果实"],"growthStages":[],"identification":"瓜类可在茎蔓、叶片及果实受害。茎蔓初见水渍状斑，后生白色棉絮状菌丝体；果实可呈湿腐状，后期染病部位可出现黑色鼠粪状菌核。","differential":"白色菌丝和黑色菌核是重要观察点；与灰霉、其他腐烂及生理性倒伏比较，不能仅因湿腐就确认菌核病。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='78054ae7-dfcf-57dc-8b19-e4efae4d2d65' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='黄瓜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='菌核病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='78054ae7-dfcf-57dc-8b19-e4efae4d2d65' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '15004980-5494-5b8a-b794-71886682e777',1,'PUBLISHED','{"cropName":"黄瓜","cropAliases":[],"diseaseName":"粉虱","diseaseAliases":["黄瓜粉虱"],"symptomKeywords":["白色小飞虫","白色蜡粉","粉虱","叶背虫体","煤污","褪绿"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"群集在叶片背面刺吸汁液，叶片可褪绿、变黄、萎蔫，有时伴煤污。成虫虫体及翅有白色蜡粉，具有趋黄性。","differential":"黄叶或煤污不是粉虱的专有症状，须拍清叶背虫体；与蚜虫、蓟马等区分，未能观察虫体时不作虫种确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"检查并修补棚口防虫网，配合黄板监测，记录叶背虫量；低密度时由农技人员评估天敌防控。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='15004980-5494-5b8a-b794-71886682e777' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='黄瓜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='粉虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='15004980-5494-5b8a-b794-71886682e777' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'b6c5ec06-a371-5b75-b5da-d57554e7567f',1,'PUBLISHED','{"cropName":"草莓","cropAliases":[],"diseaseName":"白粉病","diseaseAliases":["草莓白粉病"],"symptomKeywords":["白色菌丝层","白粉","果面白色","叶片上卷","汤匙状","花瓣紫红"],"affectedParts":["叶片","花","果实","叶柄"],"growthStages":[],"identification":"草莓果实受害可出现薄薄的白色菌丝层。叶片可上卷呈汤匙状，花蕾、花瓣受害可呈紫红色，幼果可能失去光泽、硬化或不膨大。叶片和花果特征补充参考湖南省林业局2006-07-04《草莓病害的防治》。","differential":"果面白色物需要与灰霉、残留粉尘比较；叶卷或果实畸形也可能有其他原因。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html；叶花症状补充：https://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2613392.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='b6c5ec06-a371-5b75-b5da-d57554e7567f' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='草莓' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病'));
