INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7f4024da-22cd-599a-b707-4b831622c21e',1,'PUBLISHED','{"cropName":"草莓","cropAliases":[],"diseaseName":"灰霉病","diseaseAliases":["草莓灰霉病"],"symptomKeywords":["灰霉","灰色霉层","密生灰霉","果实软化","褐色斑点","果实腐败"],"affectedParts":["花","花瓣","果实","叶片"],"growthStages":[],"identification":"开花后花朵、花瓣、果实和叶片均可发病；膨大果实上可出现褐色斑点，逐步扩大并密生灰霉，造成果实软化腐败。","differential":"与白粉病的薄白菌丝层及其他果腐比较，优先补拍病斑边缘、霉层和果柄，不能以单一腐烂症状确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"湖南省林业局","sourceVersion":"2006-07-04；2026-11-14公开全文整理","sourceRef":"《草莓病害的防治》对应病害症状段；历史资料只作识别参考；https://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2613392.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7f4024da-22cd-599a-b707-4b831622c21e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='草莓' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='灰霉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7f4024da-22cd-599a-b707-4b831622c21e' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a0dc10ee-18d0-5561-b406-ee45810e3401',1,'PUBLISHED','{"cropName":"草莓","cropAliases":[],"diseaseName":"叶斑病","diseaseAliases":["蛇眼病","草莓叶斑病","草莓蛇眼病"],"symptomKeywords":["蛇眼状","暗紫色小斑","中央灰白","紫红褐色","蛇眼病"],"affectedParts":["叶片","叶柄","果梗","嫩茎"],"growthStages":[],"identification":"叶片先出现暗紫色小斑点，扩大为近圆形或椭圆形斑，边缘紫红褐色、中央灰白色，略有细轮，呈蛇眼状，原资料描述病斑不形成小黑粒。也可危害叶柄、果梗等部位。","differential":"与其他叶斑、药害或缺素比较，保留斑心和斑缘特写；只有叶缘变色不能认定为蛇眼病。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"及时摘除病叶和老叶，记录新叶发病及扩展情况，清理后的残体按当地要求处理。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"湖南省林业局","sourceVersion":"2006-07-04；2026-11-14公开全文整理","sourceRef":"《草莓病害的防治》对应病害症状段；历史资料只作识别参考；https://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2613392.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='a0dc10ee-18d0-5561-b406-ee45810e3401' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='草莓' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='叶斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a0dc10ee-18d0-5561-b406-ee45810e3401' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '49709299-3ed0-54ab-8e44-df905b7af253',1,'PUBLISHED','{"cropName":"草莓","cropAliases":[],"diseaseName":"叶螨","diseaseAliases":["红蜘蛛","草莓叶螨","草莓红蜘蛛"],"symptomKeywords":["红蜘蛛","撒沙状","结网","螨体","叶面细小斑点"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"草莓生产中后期需关注红蜘蛛。叶面可呈撒沙状，叶片可明显结网，并可观察到红色、褐色或黄绿色等不同颜色螨体。","differential":"红蜘蛛为常用俗称，颜色不能单独确定螨种；结合叶背活动螨体、结网和受害斑点，与蓟马、缺素等比较。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"重点巡查叶背和结网区域，拍摄螨体近景，记录虫口范围及扩展趋势；结合棚室管理由农技人员制定处置。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='49709299-3ed0-54ab-8e44-df905b7af253' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='草莓' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='叶螨'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='49709299-3ed0-54ab-8e44-df905b7af253' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9cb2120e-ee29-51ce-8d59-b2c808613773',1,'PUBLISHED','{"cropName":"生菜","cropAliases":[],"diseaseName":"霜霉病","diseaseAliases":["生菜霜霉病"],"symptomKeywords":["黄色褪绿斑","褐色褪绿斑","叶背白色霉层","白色霉层","黄斑"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"叶菜类染病时叶片正面可有黄色和褐色褪绿斑，叶背产生白色霉层。原资料以叶菜类及油麦菜展示症状，本条仅作叶菜霜霉候选筛查。","differential":"需比较受害叶片正反面，只有黄斑不能排除其他叶斑、药害或缺素，必要时采样确认病原。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9cb2120e-ee29-51ce-8d59-b2c808613773' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='生菜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='霜霉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9cb2120e-ee29-51ce-8d59-b2c808613773' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1be90129-b7fc-5e9b-bc7d-6241a13312d2',1,'PUBLISHED','{"cropName":"生菜","cropAliases":[],"diseaseName":"菌核病","diseaseAliases":["生菜菌核病"],"symptomKeywords":["白色菌丝","黑色菌核","鼠粪状","棉絮状","近地叶腐烂","瘫烂"],"affectedParts":["根部","外叶","近地叶"],"growthStages":[],"identification":"叶菜菌核病多从根部、外叶或近地叶发生，叶片湿腐状坏死、瘫烂，并伴白色菌丝；适宜条件下后期出现黑色鼠粪状菌核，原资料含生菜受害示例。","differential":"与软腐和其他基部腐烂比较，重点查白色菌丝及黑色菌核，缺乏这些证据时保留疑似。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1be90129-b7fc-5e9b-bc7d-6241a13312d2' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='生菜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='菌核病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1be90129-b7fc-5e9b-bc7d-6241a13312d2' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1cc13aa2-1755-5a61-9d18-d75d1b0ffe8e',1,'PUBLISHED','{"cropName":"白菜","cropAliases":["大白菜","小白菜"],"diseaseName":"小菜蛾","diseaseAliases":["吊丝虫","两头尖","小青虫","白菜小菜蛾"],"symptomKeywords":["透明斑块","只剩叶脉","叶片孔洞","吊丝虫","两头尖","小青虫"],"affectedParts":["叶片","心叶","嫩茎"],"growthStages":[],"identification":"幼虫黄绿或深绿、两端尖细，臀足向后伸出腹末；初孵幼虫潜入叶肉，随后取食下表皮和叶肉留下透明上表皮，较大幼虫可食成孔洞，严重时只剩叶脉。成虫合翅时可见相连菱形斑。","differential":"孔洞可能由菜青虫等其他食叶害虫造成，须结合幼虫体形、虫态及叶背取食证据，不能把俗称小青虫直接当种类结论。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"收获后处理残枝落叶并及时灭茬，尽量避免十字花科周年连作；由农技人员结合监测评估性诱或理化诱控。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"上海市农业农村委员会 / 上海市农业技术推广服务中心","sourceVersion":"2018-11-19；2026-11-14公开全文整理","sourceRef":"《蔬菜植保技术（九）》小菜蛾的识别、危害与农业理化防治；https://nyncw.sh.gov.cn/nyjs/20181121/0009-107437.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1cc13aa2-1755-5a61-9d18-d75d1b0ffe8e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='白菜' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='小菜蛾'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1cc13aa2-1755-5a61-9d18-d75d1b0ffe8e' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'd9d4fca5-09ee-5d90-bff5-8d3ae22c9d7f',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"稻瘟病","diseaseAliases":["稻热病","叶瘟","穗颈瘟","水稻稻瘟病"],"symptomKeywords":["梭形","黄色晕圈","褐色坏死线","穗颈变褐","白穗","稻节变黑","灰色霉层"],"affectedParts":["叶片","稻节","穗颈","穗部","谷粒"],"growthStages":["分蘖期","拔节期","抽穗期"],"identification":"慢性叶瘟常呈梭形，边缘黄色晕圈、内圈黄褐、中间灰白，两端沿叶脉有褐色坏死线。急性斑可呈暗绿水渍状近圆或椭圆斑；稻节可变黑易折断，穗颈病变褐可形成枯白穗。","differential":"白穗也可由螟害等原因造成，应检查穗颈和茎秆；水渍斑也需与其他病害区分，结合生育期采样复核。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合当地推广建议选用抗病品种并合理布局，科学管理肥水，避免偏施或过施氮肥；加强叶部和穗期巡查预警，具体水分管理由农技人员结合生育期指导。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"温岭市农业农村和水利局","sourceVersion":"2024-07-15；2026-11-14公开全文整理","sourceRef":"《警惕！水稻中的癌症——稻瘟病》田间症状与农业防治；https://www.wl.gov.cn/art/2024/7/15/art_1633390_59058339.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='d9d4fca5-09ee-5d90-bff5-8d3ae22c9d7f' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='稻瘟病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='d9d4fca5-09ee-5d90-bff5-8d3ae22c9d7f' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'f95daee3-63fe-5433-9414-ffcf49a569d7',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"纹枯病","diseaseAliases":["水稻纹枯病"],"symptomKeywords":["云纹状","水渍状暗绿色","灰白色病斑","叶鞘病斑","暗褐色菌核","蛛丝状菌丝"],"affectedParts":["叶鞘","叶片","茎秆","穗部"],"growthStages":["分蘖期","孕穗期","抽穗期"],"identification":"近水面叶鞘先出现水渍状暗绿斑，扩大为椭圆或云纹状褐斑，中央草黄至灰白、边缘褐至暗褐，重时汇合为云纹状大斑块。潮湿时可见白或灰白蛛丝状菌丝，后形成暗褐菌核。","differential":"重点观察近水面叶鞘、云纹病斑及菌核；不能用叶片发黄或枯穗单独判定，注意与稻瘟等区分。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"重病地块结合当地要求处理病稻草，整地时打捞菌核；合理密植、通风透光，科学灌溉施肥，并记录病丛分布。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"黑龙江省农业农村厅","sourceVersion":"2026-07-28；2026-11-14公开全文整理","sourceRef":"《水稻纹枯病识别与防治技术》症状与防治建议第1项；https://nynct.hlj.gov.cn/nynct/c115393/202607/c00_31962846.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='f95daee3-63fe-5433-9414-ffcf49a569d7' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='纹枯病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='f95daee3-63fe-5433-9414-ffcf49a569d7' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'be47f88f-1ed8-5695-9460-1e78615eca57',1,'PUBLISHED','{"cropName":"茄子","cropAliases":[],"diseaseName":"蚜虫","diseaseAliases":["茄子蚜虫"],"symptomKeywords":["群集小虫","腹管","叶片卷曲","嫩梢畸形","蚜虫"],"affectedParts":["嫩梢","叶片","叶背"],"growthStages":[],"identification":"蚜虫常群集嫩梢和叶背刺吸汁液，导致叶片卷曲、畸形。虫体约1至5毫米、圆或椭圆，体色多样，腹部具管状突起，原资料含茄子寄主示例。","differential":"叶片卷曲也可能与病毒、药害或缺素有关，需观察叶背群集虫体和腹管；发现蚜虫也不能排除伴发病毒。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"巡查嫩梢叶背，检查防虫网，配合黄板监测；低虫量时由农技人员评估瓢虫等天敌防控，保留伴发症状用于复核。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='be47f88f-1ed8-5695-9460-1e78615eca57' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茄子' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚜虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='be47f88f-1ed8-5695-9460-1e78615eca57' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1b0490cd-01f6-5516-8208-7e28cd05acdc',1,'PUBLISHED','{"cropName":"茄子","cropAliases":[],"diseaseName":"粉虱","diseaseAliases":["茄子粉虱"],"symptomKeywords":["白色小飞虫","白色蜡粉","粉虱","叶背虫体","煤污","褪绿"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"群集在叶片背面刺吸汁液，叶片可褪绿、变黄、萎蔫，有时伴煤污。成虫虫体及翅有白色蜡粉，具有趋黄性。 原资料含茄子寄主示例。","differential":"黄叶或煤污不是粉虱的专有症状，须拍清叶背虫体；与蚜虫、蓟马等区分，未能观察虫体时不作虫种确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"检查并修补棚口防虫网，配合黄板监测，记录叶背虫量；低密度时由农技人员评估天敌防控。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1b0490cd-01f6-5516-8208-7e28cd05acdc' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茄子' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='粉虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1b0490cd-01f6-5516-8208-7e28cd05acdc' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a874ed4c-d6f8-58b0-89de-60c81dafbd39',1,'PUBLISHED','{"cropName":"辣椒","cropAliases":["椒"],"diseaseName":"白粉病","diseaseAliases":["辣椒白粉病"],"symptomKeywords":["白粉","叶背白色粉状","白色粉状物","叶背霉斑"],"affectedParts":["叶片","叶背"],"growthStages":[],"identification":"椒类白粉病在叶背表现较明显，后期可密布白色粉状物；检查叶背病部并结合症状发展观察。","differential":"应与粉尘、喷药残留及其他叶背霉层比较；白色附着物本身不能单独确诊。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"结合现场调节通风和湿度，避免骤冷骤热；巡查并记录扩展情况，病叶病果和残体按当地植保要求处理，减少传播。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='a874ed4c-d6f8-58b0-89de-60c81dafbd39' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='辣椒' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a874ed4c-d6f8-58b0-89de-60c81dafbd39' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'fc7e8e5c-986f-5ced-9958-6239cb8ad693',1,'PUBLISHED','{"cropName":"辣椒","cropAliases":[],"diseaseName":"蓟马","diseaseAliases":["辣椒蓟马"],"symptomKeywords":["银白色斑痕","银白斑","细长小虫","花朵褐变","落花落果","蓟马"],"affectedParts":["花","嫩梢","叶片"],"growthStages":[],"identification":"花、嫩梢、叶片可受害，叶片出现银白色斑痕，花朵可褐变、畸形，严重时落花落果。成虫微小细长，多为黄褐色或黑色，活动隐蔽。","differential":"银白斑痕应结合花内或嫩梢细长虫体观察，与螨害、擦伤或药害区分；仅凭花畸形不能确定蓟马。 本条为公开资料整理的候选识别依据，不能单凭关键词确诊；补拍整株、受害部位正反面及近景，保留症状时间和近期用药记录，证据不足或病情加重交农技人员复核。","measures":"检查花、嫩梢和叶背，记录虫量和受害范围；修补防虫网，配合蓝板监测，天敌释放由农技人员评估。 不提供农药品种、剂量、混配或安全间隔；需要用药时由专业人员核对当前有效登记、作物和防治对象。","source":"北京市农业农村局 / 北京市植物保护站","sourceVersion":"2025-03-31；2026-11-14公开全文整理","sourceRef":"《想要“苗壮壮”,收好这份春季设施蔬菜病虫管控锦囊》；https://nyncj.beijing.gov.cn/nyj/zwgk/ztgk/zwbhxx/743577313/index.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='fc7e8e5c-986f-5ced-9958-6239cb8ad693' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='辣椒' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='fc7e8e5c-986f-5ced-9958-6239cb8ad693' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a101',1,'PUBLISHED','{"cropName":"小麦","cropAliases":["麦子"],"diseaseName":"条锈病","diseaseAliases":["小麦条锈病","黄锈病"],"symptomKeywords":["条锈","鲜黄色夏孢子堆","黄色条状","叶脉平行","锈病发病中心"],"affectedParts":["叶片","叶鞘","茎秆","穗部"],"growthStages":["返青期","拔节期","抽穗期"],"identification":"主要侵染小麦叶片，也可见于叶鞘、茎秆和穗部。病部出现鲜黄色或黄褐色夏孢子堆，通常沿叶脉排列成条状；后期可形成黑色冬孢子堆。田间常先出现局部发病中心，再向周边扩展。","differential":"条状排列和鲜黄色锈状孢子堆是重要观察点，需与叶锈病散生病斑、白粉病霉层及机械擦伤区分。出现单片病叶或疑似发病中心时应补拍整株、叶片正反面和病斑近景，并交农技人员复核，不凭单张照片确认流行范围。","measures":"加强田间巡查和区域监测，发现疑似发病中心及时标记、复查并按属地植保要求采取分区控制；合理选用抗病品种，做好田间卫生和适期管理。是否用药及用药窗口须结合当地监测、有效登记和农技人员意见。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-28；2025-02-28；2026-11-14整理","sourceRef":"《小麦“三病一虫”防控技术要点》及《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240328_6452619.htm；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a101' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='小麦' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='条锈病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a101' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a102',1,'PUBLISHED','{"cropName":"小麦","cropAliases":["麦子"],"diseaseName":"赤霉病","diseaseAliases":["小麦赤霉病","穗腐病"],"symptomKeywords":["穗腐","粉红色霉层","粉红色胶质霉层","小穗枯死","籽粒皱缩","扬花期阴雨"],"affectedParts":["穗部","小穗","籽粒"],"growthStages":["抽穗期","扬花期","灌浆期"],"identification":"穗部和小穗是主要受害部位，发病小穗可提前枯死，湿度适宜时病部可见粉红色或粉红色胶质霉层，后期籽粒可能皱缩、变色。抽穗扬花期连续阴雨、露水或高湿条件会增加发生风险。","differential":"穗部枯死、霉层和天气条件应结合观察，需与穗部机械损伤、冻害、其他穗腐或成熟期自然变色区分。疑似时补拍整穗、病健交界和籽粒近景，并按粮食质量安全要求交专业人员采样复核。","measures":"重点关注抽穗至扬花期天气和田间湿度，做好监测预警、合理水肥管理及区域统防统治组织。具体预防时机和投入品须按当地植保方案、当前有效登记及农技人员意见执行，不能由图谱直接生成处方。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-28；2025-02-28；2026-11-14整理","sourceRef":"《小麦“三病一虫”防控技术要点》及《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240328_6452619.htm；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a102' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='小麦' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='赤霉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a102' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a103',1,'PUBLISHED','{"cropName":"小麦","cropAliases":["麦子"],"diseaseName":"茎基腐病","diseaseAliases":["小麦茎基腐病","茎基部病害"],"symptomKeywords":["茎基腐","茎基部褐变","茎基部腐烂","基部病斑","植株早枯","白穗"],"affectedParts":["茎基部","茎秆","根部"],"growthStages":["返青期","拔节期","灌浆期"],"identification":"病害主要发生在小麦茎基部和根部，病部可出现褐变、腐烂，严重时植株早枯、形成白穗或穗粒发育不良。田间常表现为成片或点片发生，需结合茎基部剖面、根系和整株长势观察。","differential":"茎基部褐变和白穗还可能由纹枯病、根腐病、冻害、干旱或其他生理因素造成，应同时检查根系、茎基部病斑、田间水肥和倒伏情况。仅凭白穗不能确诊，建议采集病健交界组织送检。","measures":"选用健康种子和适宜抗性品种，做好播前处理、合理密植和水肥管理；早春重点巡查茎基部，发现点片异常及时标记和复核。病残体处理及用药由当地植保部门结合登记信息指导。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-28；2025-02-28；2026-11-14整理","sourceRef":"《小麦“三病一虫”防控技术要点》及《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240328_6452619.htm；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a103' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='小麦' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='茎基腐病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a103' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a104',1,'PUBLISHED','{"cropName":"小麦","cropAliases":["麦子"],"diseaseName":"白粉病","diseaseAliases":["小麦白粉病"],"symptomKeywords":["白粉","白色粉状霉层","白色霉斑","叶片覆粉","黑色小粒"],"affectedParts":["叶片","叶鞘","茎秆","穗部"],"growthStages":["返青期","拔节期","抽穗期"],"identification":"叶片、叶鞘和茎秆表面可出现白色粉状霉层，病斑可逐渐扩大并覆盖叶面；后期霉层中可能出现黑色小粒。病害程度与品种、群体密度和田间湿度等因素有关。","differential":"需与灰尘、药液残留、霜霉状物和其他叶部病害区分，重点观察霉层是否附着、扩展及是否有黑色小粒。只有叶片黄化或干枯时不能判定白粉病，应补拍病斑近景和叶片正反面。","measures":"选用适宜抗性品种，合理密植、控制群体郁闭，改善通风透光并加强巡查；病叶率达到当地防控指标时由农技人员制定处置方案。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2025-02-28；2026-11-14整理","sourceRef":"《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a104' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='小麦' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a104' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a105',1,'PUBLISHED','{"cropName":"小麦","cropAliases":["麦子"],"diseaseName":"蚜虫","diseaseAliases":["小麦蚜虫","麦蚜"],"symptomKeywords":["蚜虫","穗蚜","群集刺吸","叶片卷曲","蜜露","煤污"],"affectedParts":["叶片","叶鞘","茎秆","穗部"],"growthStages":["返青期","拔节期","抽穗期","灌浆期"],"identification":"蚜虫可在叶片、叶鞘、茎秆和穗部群集取食，造成叶片失绿、卷曲或长势衰弱，穗期可集中在穗部危害，并可能伴随蜜露和煤污。应结合虫体、虫量、天敌数量和受害范围观察。","differential":"黄化、卷叶和长势弱也可能由缺素、干旱、药害或根部问题造成；煤污和蜜露不能替代虫体观察。应拍清穗部、叶背和茎秆上的虫体，记录百株或百穗虫量，避免把其他小型害虫混判为蚜虫。","measures":"加强返青拔节至灌浆期监测，保护天敌并记录虫量变化；点片发生时按当地指标开展分区处置，必要时组织统防统治。投入品及使用条件须由农技人员按当前登记和安全间隔核对。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-28；2025-02-28；2026-11-14整理","sourceRef":"《小麦“三病一虫”防控技术要点》及《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240328_6452619.htm；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a105' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='小麦' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚜虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a105' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a106',1,'PUBLISHED','{"cropName":"玉米","cropAliases":["玉蜀黍"],"diseaseName":"南方锈病","diseaseAliases":["玉米南方锈病"],"symptomKeywords":["南方锈病","黄褐色疱斑","锈色孢子堆","叶片锈斑","叶片早衰"],"affectedParts":["叶片","叶鞘","苞叶"],"growthStages":["拔节期","抽雄期","灌浆期"],"identification":"叶片、叶鞘和苞叶等部位可出现黄褐色或锈色小疱斑，病斑破裂后散出锈色粉状物，严重时叶片早衰并影响灌浆。发生程度与品种、区域和中后期气象条件有关。","differential":"需与北方锈病、叶斑病及机械擦伤区分，重点观察孢子堆颜色、形态和在叶片上的分布。单个黄褐色斑点不能确认南方锈病，疑似时补拍叶片正反面、整株和田间分布情况。","measures":"选用适宜抗性品种，合理密植、科学施肥，加强中后期巡查和区域监测；达到当地防控指标时由植保人员组织分区处置。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-08；2025-02-28；2026-11-14整理","sourceRef":"《2024年玉米重大病虫害防控技术方案》及《2025年粮食作物重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240308_6450963.htm；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a106' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='玉米' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='南方锈病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a106' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a107',1,'PUBLISHED','{"cropName":"玉米","cropAliases":["玉蜀黍"],"diseaseName":"大斑病","diseaseAliases":["玉米大斑病","叶斑病"],"symptomKeywords":["大斑病","长梭形病斑","灰褐色大斑","叶片大斑","叶片干枯"],"affectedParts":["叶片","叶鞘","苞叶"],"growthStages":["拔节期","抽雄期","灌浆期"],"identification":"叶部病害，病斑可从下部叶片向上扩展，常呈长梭形或长条形灰褐色斑，严重时多个病斑融合，叶片提前干枯并影响籽粒灌浆。田间可见同一植株不同叶位受害程度不一。","differential":"需与小斑病、弯孢叶斑病、锈病和药害区分，重点观察病斑长度、形状、颜色和叶脉关系。叶片单纯黄化或干边不能直接判定大斑病，应补拍病斑近景、叶片正反面和整株叶位。","measures":"选用抗性品种，合理密植、科学施肥并及时清理严重病残体；加强拔节至灌浆期巡查，发现病斑扩展及时由农技人员复核并制定处置方案。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-08；2022-02-24；2026-11-14整理","sourceRef":"《2024年玉米重大病虫害防控技术方案》及《2022年玉米重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240308_6450963.htm；http://www.moa.gov.cn/ztzl/ddymdzfhjs/jszd_29063/202202/t20220224_6389604.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a107' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='玉米' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='大斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a107' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a108',1,'PUBLISHED','{"cropName":"玉米","cropAliases":["玉蜀黍"],"diseaseName":"小斑病","diseaseAliases":["玉米小斑病","叶斑病"],"symptomKeywords":["小斑病","褐色小斑","椭圆形小斑","水渍状小点","紫红色边缘","叶片斑点"],"affectedParts":["叶片","叶鞘","苞叶"],"growthStages":["拔节期","抽雄期","灌浆期"],"identification":"初期可见浅褐色或水渍状小点，随后形成较小的椭圆形或条形褐色病斑，部分病斑边缘可呈紫红色；严重时病斑融合造成叶片早衰。大小斑病可能在同一田块或同一叶片混合发生。","differential":"需与大斑病、锈病、褐斑病和药害区分，重点记录斑点大小、形态、边缘颜色及是否沿叶脉扩展。仅有叶片黄斑、焦边或零星斑点不足以确诊，建议补拍整株和病斑尺度参照。","measures":"选用抗性品种，合理密植并做好田间通风、肥水和病残体管理；加强拔节至灌浆期监测，达到当地指标后由植保人员确定处置。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-08；2022-02-24；2026-11-14整理","sourceRef":"《2024年玉米重大病虫害防控技术方案》及《2022年玉米重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240308_6450963.htm；http://www.moa.gov.cn/ztzl/ddymdzfhjs/jszd_29063/202202/t20220224_6389604.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a108' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='玉米' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='小斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a108' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a109',1,'PUBLISHED','{"cropName":"玉米","cropAliases":["玉蜀黍"],"diseaseName":"玉米螟","diseaseAliases":["玉米螟虫","玉米钻心虫"],"symptomKeywords":["玉米螟","心叶蛀孔","花叶","蛀茎","蛀穗","虫粪"],"affectedParts":["心叶","茎秆","雄穗","雌穗","果穗"],"growthStages":["苗期","心叶期","抽雄期","灌浆期"],"identification":"幼虫可在心叶、叶鞘、茎秆、雄穗和雌穗等部位取食或蛀入，心叶期可出现孔洞、花叶或虫粪，后期蛀茎、蛀穗会影响输导和果穗发育。需结合蛀孔、虫粪、幼虫或成虫监测判断。","differential":"心叶孔洞也可能由草地贪夜蛾、粘虫等造成，蛀茎和穗部症状需与其他蛀食性害虫区分。观察时应拍清心叶、茎秆蛀孔、虫粪和穗部，必要时结合诱捕监测或采样鉴定。","measures":"做好秸秆处理、深耕灭茬和田间巡查，成虫期可结合当地条件开展灯诱、性诱或保护天敌；幼虫低龄期是综合防控的重要窗口，具体措施由植保人员按区域方案确定。","source":"农业农村部 / 全国农业技术推广服务中心","sourceVersion":"2024-03-08；2022-02-24；2026-11-14整理","sourceRef":"《2024年玉米重大病虫害防控技术方案》及《2022年玉米重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240308_6450963.htm；http://www.moa.gov.cn/ztzl/ddymdzfhjs/jszd_29063/202202/t20220224_6389604.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a109' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='玉米' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='玉米螟'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a109' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9e7f8a21-0e77-5c6a-8f48-11e9c7d8a110',1,'PUBLISHED','{"cropName":"玉米","cropAliases":["玉蜀黍"],"diseaseName":"草地贪夜蛾","diseaseAliases":["草地贪夜蛾幼虫","秋黏虫"],"symptomKeywords":["草地贪夜蛾","倒Y形纹","四个黑点","窗孔","不规则孔洞","心叶取食","叶片缺刻"],"affectedParts":["叶片","心叶","叶鞘","雄穗","雌穗"],"growthStages":["苗期","心叶期","抽雄期","灌浆期"],"identification":"低龄幼虫常隐藏在心叶、叶鞘等部位取食，叶片可出现半透明窗孔；大龄幼虫可造成不规则长形孔洞，并钻蛀心叶、雄穗或幼嫩雌穗。幼虫三龄后头部可见倒Y形纹，末端腹节背面有四个近方形排列的黑点，是重要识别特征。","differential":"孔洞、缺刻和心叶受害也可能由玉米螟、粘虫或其他夜蛾类害虫造成，不能只凭叶片缺口判定。应拍清幼虫头部、末端腹节黑点、心叶内虫粪和受害部位，必要时结合成虫诱捕及专业鉴定。","measures":"加强苗期、心叶期和幼嫩穗部巡查，成虫期可结合连片灯诱、食诱或性诱监测，优先关注低龄幼虫窗口并保护天敌。涉及应急处置时须按属地植保方案、当前登记和安全要求执行。","source":"农业农村部 / 全国农业技术推广服务中心；地方农业农村部门","sourceVersion":"2024-03-08；2022-02-24；2026-11-14整理","sourceRef":"《2024年玉米重大病虫害防控技术方案》及《2022年玉米重大病虫害防控技术方案》；https://www.moa.gov.cn/gk/nszd_1/nszd_2/202403/t20240308_6450963.htm；http://www.moa.gov.cn/ztzl/ddymdzfhjs/jszd_29063/202202/t20220224_6389604.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a110' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='玉米' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='草地贪夜蛾'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9e7f8a21-0e77-5c6a-8f48-11e9c7d8a110' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1d6461df-568c-564a-b7a7-6b4b7da89960',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"稻曲病","diseaseAliases":["水稻稻曲病","绿霉粒","霉谷病"],"symptomKeywords":["稻曲球","黄绿色菌块","墨绿色粉末","谷粒膨大","颖壳包裹","绿霉粒"],"affectedParts":["穗部","谷粒"],"growthStages":["抽穗期","扬花期","乳熟期"],"identification":"主要观察穗上部分谷粒。受害颖壳可张开并露出黄绿色块状突起，逐渐膨大包裹颖壳，成为比正常谷粒大的近球形菌块；后期变为黄绿或墨绿色，表面龟裂可散出墨绿色粉末。","differential":"与黑粉类穗病、其他穗腐及附着污物比较，重点拍摄独立膨大的菌块和颖壳关系；黄叶、白穗或秕粒不能单独确诊，孕穗期未见菌块也不能排除感染。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"选用适宜的抗耐病品种，避免偏施、迟施氮肥；关注孕穗至抽穗期天气和当地预警，记录病穗分布，病残体按当地要求离田处理。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"广西农业科学院（转载《东阳日报》）；农业农村部 / 全国农技推广服务中心","sourceVersion":"2012-11-07；2025-02-28；2026-11-14整理","sourceRef":"识别：《如何防治水稻稻曲病》症状段；http://www.gxaas.net/front/detail/132/3697/67399；管理：《2025年水稻重大病虫害防控技术方案》；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1d6461df-568c-564a-b7a7-6b4b7da89960' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='稻曲病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1d6461df-568c-564a-b7a7-6b4b7da89960' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '03105143-945b-5939-b272-8f2d2706111d',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"恶苗病","diseaseAliases":["水稻恶苗病"],"symptomKeywords":["节间伸长","病苗细高","叶色较淡","植株徒长","浅红色霉层","白粉霉状物","穗小不实"],"affectedParts":["茎秆","叶片","叶鞘","谷粒"],"growthStages":["秧苗期","分蘖期","抽穗期"],"identification":"病株节间伸长、细而高，颜色较淡；茎秆内可见白色霉状物，随后变淡红色，部分可见黑色小点。病株可能抽穗偏早、穗小、谷粒少或不实，死株及病谷可有浅红色或白粉状霉物。","differential":"与密播弱光徒长、营养失衡及其他苗期枯死原因比较；只见苗高或叶色淡不能确诊，应补拍病健株对比、茎节和霉层并核查种源。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"选择健康种源，不移栽可疑病苗；发现异常细高苗及时标记并请农技人员确认，按当地要求清除病株、处理病稻草和育秧材料，避免病残体随意堆放。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"云浮市农业农村局（转载种植问答网）；农业农村部 / 全国农技推广服务中心","sourceVersion":"2018-04-24；2025-02-28；2026-11-14整理","sourceRef":"识别：《水稻恶苗病防治方法》症状段；https://www.yunfu.gov.cn/nyncj/zdht/syjs/content/post_378144.html；管理：2025年水稻防控方案；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='03105143-945b-5939-b272-8f2d2706111d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='恶苗病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='03105143-945b-5939-b272-8f2d2706111d' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e2bcfa76-ab07-56f4-86db-9a4fe00d102e',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"白叶枯病","diseaseAliases":["水稻白叶枯病"],"symptomKeywords":["叶缘波纹","黄色长条形","枯白色","淡黄色菌脓","鱼籽状菌脓","绿白分明"],"affectedParts":["叶片","叶尖","叶缘"],"growthStages":["分蘖期","孕穗期","抽穗期"],"identification":"叶尖、叶缘起病，可由暗绿色小斑逐渐形成黄色至枯白色长条病斑，病健交界较明显、可呈波纹形；潮湿时病部可溢淡黄色菌脓，干后可呈鱼籽状。","differential":"需与细菌性条斑病、条纹叶枯病、生理早衰和药肥害区分；观察起病位置、斑缘及菌脓，黄叶或干尖不足以确诊，疑似细菌性病害建议采样检测。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"合理布局抗耐病品种、避免偏施氮肥和串灌；关注台风暴雨后的新病斑，减少湿叶摩擦和伤口，记录发病中心并交属地农技人员指导处理。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"杭州市临安区政府门户（转载中国农业网）；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-01-23；2025-02-28；2026-11-14整理","sourceRef":"识别：《水稻虫害防治技术》白叶枯病黄叶段；http://www.linan.gov.cn/art/2015/1/23/art_1367634_11441700.html；管理：2025年水稻防控方案；https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='e2bcfa76-ab07-56f4-86db-9a4fe00d102e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白叶枯病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='e2bcfa76-ab07-56f4-86db-9a4fe00d102e' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '5f0b2a50-b505-5ec7-9bda-ba844b5bdf0b',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"条纹叶枯病","diseaseAliases":["水稻条纹叶枯病"],"symptomKeywords":["断续黄白条斑","黄绿色条斑","纸捻状","假枯心","心叶弯曲下垂","分蘖减少"],"affectedParts":["叶片","心叶","整株"],"growthStages":["秧苗期","分蘖期"],"identification":"叶片可出现断续黄白色或黄绿色条斑，病株分蘖减少、抽穗不良。心叶可卷成纸捻状并弯曲下垂，形成假枯心；与螟害比较时，基部通常无虫孔、不腐烂，心叶不易拔出。","differential":"本条为病毒病疑似识别依据；须与螟害真枯心、黑条矮缩病、缺素和药害鉴别，不能仅凭条斑判定病毒。灰飞虱传播背景只能作为上下文，确证需采样检测。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"选抗耐病品种、采用健康秧苗；结合当地植保监测，重点巡查秧田至分蘖前期灰飞虱和异常条斑，病苗处理及媒介控制由农技人员指导。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"杭州市临安区政府门户（转载中国农业网）；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-02-03；2015-01-23；2025-02-28；2026-11-14整理","sourceRef":"识别：《水稻常见病虫害及防治》条纹叶枯病段；http://www.linan.gov.cn/art/2015/2/3/art_1367634_11441856.html；假枯心鉴别：http://www.linan.gov.cn/art/2015/1/23/art_1367634_11441700.html；管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='5f0b2a50-b505-5ec7-9bda-ba844b5bdf0b' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='条纹叶枯病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='5f0b2a50-b505-5ec7-9bda-ba844b5bdf0b' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e256a871-45a7-50f7-a966-fe5282c2027d',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"胡麻斑病","diseaseAliases":["胡麻病","水稻胡麻斑病","水稻胡麻病"],"symptomKeywords":["芝麻状病斑","椭圆形褐斑","针头大小斑点","中央灰黄色","黑褐色斑点","无坏死线"],"affectedParts":["叶片"],"growthStages":[],"identification":"叶片先见针头大小斑点，逐步形成类似芝麻的椭圆形黑褐色斑；可见外围黄晕、较宽黑褐色边缘和灰黄色中心，病斑两端无稻瘟病典型坏死线。","differential":"重点与稻瘟病及其他叶斑、药害比较，拍清斑形、中心颜色和两端是否有坏死线；圆斑或黄晕都不是专有特征。本条历史资料仅提取症状，不沿用原文药剂。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"记录病叶比例和斑点扩展，核查田间肥水、根系及近期管理；结合土壤和长势由农技人员调整肥水，避免在病因未明时盲目追肥或施药。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"杭州市临安区政府门户（转载中国农业网）","sourceVersion":"2015-01-23；2026-11-14整理","sourceRef":"《水稻虫害防治技术》二、水稻病状识别技术—胡麻病叶斑段；历史资料只作识别参考；http://www.linan.gov.cn/art/2015/1/23/art_1367634_11441700.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='e256a871-45a7-50f7-a966-fe5282c2027d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='胡麻斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='e256a871-45a7-50f7-a966-fe5282c2027d' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '3deac77a-a6ee-54ce-8846-3e6489d3c0bb',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"二化螟","diseaseAliases":["水稻二化螟"],"symptomKeywords":["枯鞘","枯心","蛀茎","虫孔","虫粪","五条纵线","半枯穗"],"affectedParts":["叶鞘","茎秆","心叶","穗部"],"growthStages":["分蘖期","孕穗期","抽穗期"],"identification":"幼虫钻蛀叶鞘及茎秆，可造成枯鞘、枯心、枯孕穗或白穗。螟害枯心下部可见虫孔、虫粪，心叶较易抽出；原识别资料描述二化螟幼虫体背有五条纵线。","differential":"枯心、白穗也可由三化螟、大螟、穗颈瘟及其他病因造成；钻心虫是类群俗称，不作为二化螟专有别名。须补拍幼虫、茎秆虫孔和虫粪，不能仅凭白穗定虫种。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"调查枯鞘株和新虫孔，结合当地诱捕信息掌握虫龄；农闲期由农技人员指导低茬收割、稻桩处理和连片灭源；成虫期可连片性诱监测，保护天敌。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"杭州市临安区政府门户（转载中国农业网）；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-02-03；2015-01-23；2025-02-28；2026-11-14整理","sourceRef":"识别：《水稻常见病虫害及防治》钻心虫段；http://www.linan.gov.cn/art/2015/2/3/art_1367634_11441856.html；枯心鉴别：http://www.linan.gov.cn/art/2015/1/23/art_1367634_11441700.html；管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='3deac77a-a6ee-54ce-8846-3e6489d3c0bb' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='二化螟'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='3deac77a-a6ee-54ce-8846-3e6489d3c0bb' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '63675afc-684c-52ec-b5c4-6fb09fe8c38e',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"稻纵卷叶螟","diseaseAliases":["卷叶虫","白叶虫","水稻稻纵卷叶螟","水稻纵卷叶螟"],"symptomKeywords":["纵卷成筒","虫苞","条状白斑","吐丝卷叶","白叶满田","仅留表皮"],"affectedParts":["叶片","心叶","剑叶"],"growthStages":["分蘖期","拔节期","孕穗期","抽穗期"],"identification":"幼虫吐丝缀叶，使叶片纵卷成筒状虫苞，藏在其中取食叶肉，仅留白色表皮；受害叶可出现长短不一条状白斑，严重时白叶增多。初孵幼虫也可在心叶形成针头状小点。","differential":"与稻蓟马、缺水等造成的卷叶以及风擦伤白斑比较；重点查看丝缀虫苞、内部幼虫和取食后的白色表皮，只有卷叶不能确诊。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"巡查新虫苞并记录百丛发生量，结合当地监测掌握低龄幼虫窗口、孕穗和剑叶受害情况；在农技人员指导下开展连片性诱和天敌保护，不将某地某年的防治日期套用于所有地块。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"闽侯县人民政府；农业农村部 / 全国农技推广服务中心","sourceVersion":"2021-12-15；2025-02-28；2026-11-14整理","sourceRef":"识别：《水稻纵卷叶螟怎么识别与防治？？》危害特点与症状；http://www.minhou.gov.cn/xjwz/hdjl/znhd/nlmy/202112/t20211215_4269513.htm；管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='63675afc-684c-52ec-b5c4-6fb09fe8c38e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='稻纵卷叶螟'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='63675afc-684c-52ec-b5c4-6fb09fe8c38e' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '85a6e0ef-1a3c-5885-9f06-7d6c36639f5c',1,'PUBLISHED','{"cropName":"水稻","cropAliases":["稻"],"diseaseName":"稻飞虱","diseaseAliases":["水稻稻飞虱"],"symptomKeywords":["稻飞虱","基部叶鞘虫群","茎秆小型成若虫","稻丛下部有虫","叶鞘飞虱"],"affectedParts":["茎秆","叶鞘","稻丛基部"],"growthStages":["分蘖期","孕穗期","抽穗期","灌浆期"],"identification":"现场重点检查稻株基部叶鞘和茎秆，稻飞虱成虫及若虫主要栖息于这些隐蔽部位。本条作为稻飞虱类群候选识别，需拍清虫体并记录百丛虫量，单凭叶黄或倒伏不能判定。","differential":"褐飞虱、白背飞虱和灰飞虱须结合虫体特征及专业鉴定进一步区分，本条不将其作为等价病名别名；下部虫体也需与叶蝉等比较，不能从受害外观推断种类或带毒状态。 补拍整株、受害部位和近景，记录生育期、症状时间及近期用药；本条只提供候选识别依据，证据不足或病情加重交农技人员采样复核。","measures":"分开稻丛检查下部叶鞘和茎秆，结合迁入监测记录虫量与虫龄；避免偏施氮肥，保护蜘蛛等天敌，由农技人员按当地虫情和生育期评估防控时机，区域历史虫量不作为本地实时发生数据。 不提供药剂、剂量、混配和安全间隔；需要用药须由专业人员核对当前有效登记、作物、防治对象及属地方案，稻渔综合种养区另核对水生生物安全要求。","source":"尤溪县农业农村局 / 植保植检站；农业农村部 / 全国农技推广服务中心","sourceVersion":"2026-08-13；2025-02-28；2026-11-14整理","sourceRef":"栖息部位：《警惕稻飞虱迁入危害》施药技术要点（只提取栖息部位）；http://www.fjyx.gov.cn/ztzl/snxx/bcqb/202608/t20260813_2269624.htm；管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470753.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='85a6e0ef-1a3c-5885-9f06-7d6c36639f5c' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='水稻' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='稻飞虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='85a6e0ef-1a3c-5885-9f06-7d6c36639f5c' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'bf47242d-bfc1-55d8-b82e-f333298c5baa',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"腐烂病","diseaseAliases":["苹果腐烂病"],"symptomKeywords":["树皮腐烂","红褐色汁液","病皮变软","溃疡斑","病斑环绕枝条"],"affectedParts":["主干","主枝","侧枝","树皮"],"growthStages":["萌芽期","生长期","休眠期"],"identification":"主干、大枝及剪锯口可出现湿润红褐色病斑，病皮变软腐烂，后失水下陷、表面出现黑色小颗粒；小枝的枝枯型病斑可不呈水渍状，环绕枝条后导致枯死。","differential":"与轮纹病病瘤、日灼冻害及机械伤区分；枝枯不能直接认定腐烂病。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"合理修剪、疏花疏果、控制负载和科学肥水管理以恢复树势；病斑处理由专业人员评估，保护剪锯口并记录扩展。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='bf47242d-bfc1-55d8-b82e-f333298c5baa' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='腐烂病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='bf47242d-bfc1-55d8-b82e-f333298c5baa' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '879d1f1b-5d8e-5aa8-84eb-bddea5e7b693',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"轮纹病","diseaseAliases":["苹果轮纹病"],"symptomKeywords":["皮孔褐斑","树皮粗糙","茶褐色黏液","黄褐色腐烂","轮纹病"],"affectedParts":["枝干","果实"],"growthStages":["果实膨大期","成熟期","贮藏期"],"identification":"枝干以皮孔为中心产生红褐色近圆形或不规则病斑，可连片使树皮粗糙；果实以皮孔为中心出现水渍状褐斑，近采收期可快速扩展至果肉，呈黄褐色腐烂并流出茶褐色黏液。","differential":"需与炭疽及其他果腐、机械伤腐烂比较；轮纹状外观或单一褐斑不能独立确诊。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"加强肥水与树势管理，巡查病枝和病果并记录采前、贮藏变化；规范清园与套袋操作，残体按当地要求处理。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='879d1f1b-5d8e-5aa8-84eb-bddea5e7b693' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='轮纹病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='879d1f1b-5d8e-5aa8-84eb-bddea5e7b693' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'ef31d4c0-0fcf-5c9e-b1ff-3a1c1a7df3b2',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"斑点落叶病","diseaseAliases":["苹果斑点落叶病"],"symptomKeywords":["紫褐色斑缘","红褐色叶斑","幼果黑色亮斑","叶斑同心轮纹","斑点落叶"],"affectedParts":["叶片","新梢","果实"],"growthStages":["春梢期","秋梢期","幼果期"],"identification":"叶片初见褐色圆点，扩大为红褐色、边缘紫褐色病斑，斑心可具深色小点或同心轮纹并造成早落；幼果可出现黑色发亮小点或锈斑。","differential":"与褐斑病、炭疽叶枯病、药害比较，早期落叶不是单一病害的专有表现。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"选用健康苗木，秋冬清理落叶、病枝，保持通风透光；监测新叶病斑与落叶率，病残体按属地要求处理。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='ef31d4c0-0fcf-5c9e-b1ff-3a1c1a7df3b2' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='斑点落叶病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='ef31d4c0-0fcf-5c9e-b1ff-3a1c1a7df3b2' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1bbc6411-a2eb-52a0-b3f5-0f9d24554fbb',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"锈病","diseaseAliases":["苹果锈病"],"symptomKeywords":["黄色毛状突起","橘黄色小点","叶片肥厚肿胀","锈病"],"affectedParts":["叶片","叶背"],"growthStages":["展叶期","幼果期"],"identification":"叶正面先有褪绿斑，中央可生针尖大小橘黄色小点；叶片可肥厚肿胀，叶背黄色毛状突起为重要观察特征。","differential":"与其他叶斑及缺素区分；须同时拍摄叶正反面，周边柏类只作为流行背景，不作为确诊依据。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"巡查新叶并记录病斑；建园时结合当地要求评估转主寄主布局，不自行砍伐园外树木。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1bbc6411-a2eb-52a0-b3f5-0f9d24554fbb' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='锈病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1bbc6411-a2eb-52a0-b3f5-0f9d24554fbb' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '6c354dbe-fcf7-5f79-9256-0f3592b3d0f8',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"金纹细蛾","diseaseAliases":["苹果金纹细蛾"],"symptomKeywords":["椭圆形虫斑","叶面隆起白点","叶缘潜食","金纹细蛾"],"affectedParts":["叶片","叶背"],"growthStages":["展叶期","生长期"],"identification":"幼虫从叶背潜入叶内取食叶肉，形成椭圆形虫斑；叶片正面虫斑略隆起并有白点，后期可干枯穿孔，常发生于叶缘，多斑时叶片扭曲。","differential":"需与其他潜叶虫、病害穿孔和擦伤区分，补拍虫斑内幼虫；没有虫体证据时不确定虫种。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"清理落叶、合理去除萌蘖并处理虫源；由专业人员布设对应性诱监测，保护寄生性天敌。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='6c354dbe-fcf7-5f79-9256-0f3592b3d0f8' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='金纹细蛾'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='6c354dbe-fcf7-5f79-9256-0f3592b3d0f8' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '4c84a834-47f8-5aad-9115-a20da7bbb5a1',1,'PUBLISHED','{"cropName":"苹果","cropAliases":["苹果树"],"diseaseName":"叶螨","diseaseAliases":["苹果叶螨","红蜘蛛","苹果红蜘蛛"],"symptomKeywords":["叶面白色小斑点","叶片失绿发白","少量蛛网","红蜘蛛","叶螨"],"affectedParts":["叶片","叶背"],"growthStages":["生长期"],"identification":"主要危害叶片，初期叶面出现白色小斑点，后期叶片发白，受害处可见少量蛛网；需放大观察叶面、叶背的活动螨和卵。","differential":"本条按叶螨类群收录；红色或蛛网不能单独确定种类，不把山楂叶螨、全爪螨等不同种当成等价别名。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"记录活动螨、卵和受害叶率，保护捕食螨等天敌；捕食螨释放与园区投入品相容性由农技人员评估。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"中国农业科学技术出版社 / 苹果植保专题库；农业农村部 / 全国农技推广服务中心","sourceVersion":"2015-10；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农药与病虫草鼠害综合防控》十四、苹果树病虫害识别及农业管理段；https://apple.castp.cn/Literature/3058；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='4c84a834-47f8-5aad-9115-a20da7bbb5a1' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='苹果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='叶螨'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='4c84a834-47f8-5aad-9115-a20da7bbb5a1' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '83764149-5760-5ee0-a8ad-50f5493a634a',1,'PUBLISHED','{"cropName":"梨","cropAliases":["梨树"],"diseaseName":"黑星病","diseaseAliases":["梨黑星病"],"symptomKeywords":["黑色霉层","果面干疤","叶脉病斑","果实畸形开裂","黑星病"],"affectedParts":["果实","叶片","新梢","芽"],"growthStages":["展叶期","幼果期","果实膨大期"],"identification":"病部初有淡黄色小斑，后出现黑色霉层；果面可凹陷、硬化形成干疤并畸形、开裂；叶脉受害可干枯脱落，新梢可生疮痂状斑，病芽可枯死。","differential":"与黑斑病、擦伤及其他疮痂比较，重点观察黑霉、干疤与叶脉受害；混合感染需采样。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"巡查病芽病梢及幼果，及时记录并由农技人员指导清除病残体、排水和通风管理。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"湖南省林业局","sourceVersion":"2008-07-09；2026-11-14公开资料整理","sourceRef":"《防治梨树“三病”》识别及农业管理段；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2611183.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='83764149-5760-5ee0-a8ad-50f5493a634a' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='梨' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黑星病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='83764149-5760-5ee0-a8ad-50f5493a634a' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '289b5b4a-bf68-57e9-9926-42505bc2ff82',1,'PUBLISHED','{"cropName":"梨","cropAliases":["梨树"],"diseaseName":"锈病","diseaseAliases":["梨锈病"],"symptomKeywords":["橙黄色圆斑","针头大黄色小点","羊毛丁","梨锈病"],"affectedParts":["叶片","新梢","幼果"],"growthStages":["展叶期","幼果期"],"identification":"主要危害叶片和新梢，也可危害幼果；叶面形成有光泽的橙黄色圆形斑，表面密生针头大小黄色小点，严重时枯死脱落。","differential":"与黑星、黑斑、缺素或其他叶斑比较，需拍正反面及病斑细节；柏类寄主情况仅作背景。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"记录新叶发病与周边寄主情况，由农技人员指导果园通风及健康栽培；不自行处理园外绿化树木。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"湖南省林业局","sourceVersion":"2008-07-09；2026-11-14公开资料整理","sourceRef":"《防治梨树“三病”》识别及农业管理段；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2611183.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='289b5b4a-bf68-57e9-9926-42505bc2ff82' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='梨' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='锈病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='289b5b4a-bf68-57e9-9926-42505bc2ff82' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'de6d7c73-a4b7-54f0-865d-2759c3b273dc',1,'PUBLISHED','{"cropName":"梨","cropAliases":["梨树"],"diseaseName":"黑斑病","diseaseAliases":["梨黑斑病"],"symptomKeywords":["果面黑色斑点","同心轮纹凹陷","幼果硬化开裂","黑斑病"],"affectedParts":["果实","叶片","枝梢"],"growthStages":["幼果期","果实膨大期","成熟期"],"identification":"果面出现黑色小点，后扩大凹陷并有同心轮纹和黑色霉层；幼果可硬化开裂，成果可开裂、软化、腐败和脱落，也可感染叶片与枝梢。","differential":"与黑星病及其他果腐比较；黑色霉层不是本病专有特征，单张果实腐烂照片不足以区分。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"监测幼果、新叶和枝梢，保持通风透光，收集病落果并按当地要求处理，避免作为接穗来源。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"湖南省林业局","sourceVersion":"2008-07-09；2026-11-14公开资料整理","sourceRef":"《防治梨树“三病”》识别及农业管理段；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2611183.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='de6d7c73-a4b7-54f0-865d-2759c3b273dc' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='梨' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黑斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='de6d7c73-a4b7-54f0-865d-2759c3b273dc' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '259c17b8-af83-54c6-9a38-ca228d212ec7',1,'PUBLISHED','{"cropName":"桃","cropAliases":["桃树","油桃","蟠桃"],"diseaseName":"缩叶病","diseaseAliases":["桃缩叶病"],"symptomKeywords":["叶缘卷曲肿大","叶片红褐色","叶面灰白粉","节间短肿胀","缩叶病"],"affectedParts":["叶片","新梢","花","幼果"],"growthStages":["萌芽期","展叶期"],"identification":"叶缘卷曲肿大，叶片变红褐色，后可生灰白色粉状物，最后变褐焦枯脱落；新梢可灰绿或黄色、节间短且稍肿胀，病叶丛生，花果可畸形脱落。","differential":"与蚜虫卷叶、药害和其他生理性卷叶区分，观察是否有虫体、叶片肿胀和粉层；春季低温多雨仅作背景。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"初见病叶时由农技人员指导摘除并无害化处理；重病树结合现场恢复合理水肥，重点记录萌芽与展叶期病情。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"湖南省林业局","sourceVersion":"2003-11-13；2026-11-14公开资料整理","sourceRef":"《桃缩叶病的防治》识别及农业管理段；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2620058.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='259c17b8-af83-54c6-9a38-ca228d212ec7' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='缩叶病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='259c17b8-af83-54c6-9a38-ca228d212ec7' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '765af194-59bf-5d45-839e-051d020fe960',1,'PUBLISHED','{"cropName":"桃","cropAliases":["桃树","油桃","蟠桃"],"diseaseName":"细菌性穿孔病","diseaseAliases":["桃细菌性穿孔病"],"symptomKeywords":["水渍状绿色小点","黄绿色晕环","紫褐色斑","病斑脱落穿孔","枝条溃疡"],"affectedParts":["叶片","枝条"],"growthStages":["展叶期","生长期"],"identification":"叶片初见水渍状绿色小点，后为紫褐至黑褐色圆形或不规则斑，周围有水渍状黄绿色晕环；病健交界裂开、病组织脱落穿孔，枝条可有溃疡斑。","differential":"需与真菌性穿孔、虫食孔、机械伤区分；仅见孔洞不能判断细菌病，必要时实验室检测。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"合理修剪改善通风、排水，避免偏施氮肥；清理病枝落叶并按当地要求处理，减少湿叶作业传播。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"湖南省林业局","sourceVersion":"2004-07-13；2026-11-14公开资料整理","sourceRef":"《桃细菌性穿孔病防治》识别及农业管理段；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2617578.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='765af194-59bf-5d45-839e-051d020fe960' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='细菌性穿孔病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='765af194-59bf-5d45-839e-051d020fe960' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7630e1c6-b5e5-534f-9a59-185386d43c0d',1,'PUBLISHED','{"cropName":"桃","cropAliases":["桃树","油桃","蟠桃"],"diseaseName":"流胶病","diseaseAliases":["桃流胶病","桃树流胶"],"symptomKeywords":["枝干流胶","伤口溢胶","病部肿胀","木质部变褐"],"affectedParts":["主干","主枝","枝杈"],"growthStages":["生长期"],"identification":"主干、主枝及枝杈伤口可溢出树胶，病部稍肿，皮层与木质部变褐腐朽，严重时枝干衰弱枯死。流胶可与病原侵染及生理原因有关，排水不良、虫伤、修剪伤等可加重。","differential":"本条作为流胶综合症候候选，不凭胶液确诊真菌病；排查天牛蛀孔、冻害、机械伤及土壤积水。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"记录流胶部位、伤口、虫孔和排水情况，改善水肥与修剪管理；刮治和伤口处理须经现场专业评估，不自动生成病原性处方。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"北京市园林绿化局","sourceVersion":"2015-08-19；2026-11-14公开资料整理","sourceRef":"《桃病虫害防治》识别及农业管理段；https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120294.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7630e1c6-b5e5-534f-9a59-185386d43c0d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='流胶病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7630e1c6-b5e5-534f-9a59-185386d43c0d' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'f75af4b6-bfb5-5c0a-965c-4647163eae00',1,'PUBLISHED','{"cropName":"桃","cropAliases":["桃树","油桃","蟠桃"],"diseaseName":"桃蛀螟","diseaseAliases":["桃桃蛀螟"],"symptomKeywords":["果内充满虫粪","蛀果幼虫","蛀孔裂果","桃蛀螟"],"affectedParts":["果实"],"growthStages":["幼果期","果实膨大期","成熟期"],"identification":"幼虫蛀入果实内取食，受害果内充满虫粪，易继发裂果及腐烂。应补拍蛀孔、果内虫粪与幼虫形态。","differential":"与桃小食心虫、梨小食心虫及其他蛀果虫比较；蛀果与虫粪只能提示候选，不足以确定虫种。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"分区记录虫果并收集处理，结合成虫和卵期监测由农技人员安排物理、生物防控；避免虫果堆放在果园内。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"北京市园林绿化局","sourceVersion":"2015-08-19；2026-11-14公开资料整理","sourceRef":"《桃病虫害防治》识别及农业管理段；https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120294.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='f75af4b6-bfb5-5c0a-965c-4647163eae00' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='桃蛀螟'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='f75af4b6-bfb5-5c0a-965c-4647163eae00' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9627ea6f-d3a2-5d34-928f-ad1dc9312869',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"溃疡病","diseaseAliases":["柑橘溃疡病"],"symptomKeywords":["火山口状开裂","正反两面隆起","木栓化病斑","油浸状小点","黄色晕环"],"affectedParts":["叶片","枝梢","果实"],"growthStages":["新梢期","幼果期","果实膨大期"],"identification":"叶背初生淡黄色油浸状小点，后叶正反面同时隆起，形成灰褐色木栓化病斑，中心火山口状凹陷开裂、周围黄色晕环；枝梢斑更突起，果实斑更大且木栓化明显。","differential":"与疮痂、机械伤和潜叶蛾伤口比较，双面隆起及火山口裂纹是重点；确证需专业检测。是否属属地补充检疫对象及调运要求由植检机构核定。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"减少雨露未干时的穿园操作，合理控梢、保持通风并监测潜叶蛾伤口；发现疑似及时联系属地植保植检机构，核查繁殖材料来源和调运要求。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"安远县人民政府；农业农村部 / 全国农技推广服务中心","sourceVersion":"2026-06-01；2025-02-28；2026-11-14公开资料整理","sourceRef":"《柑橘溃疡病的发生与防治》识别及农业管理段；https://www.ay.gov.cn/ayzf/c138678depunvpuhgqd/202606/0746640db686465c960186998119811c.shtml；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9627ea6f-d3a2-5d34-928f-ad1dc9312869' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='溃疡病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9627ea6f-d3a2-5d34-928f-ad1dc9312869' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '8480b601-d218-5050-85f7-a72a56071075',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"黄龙病","diseaseAliases":["柑橘黄龙病","柑桔黄龙病"],"symptomKeywords":["斑驳黄化","新梢黄化","黄梢","红鼻子果","红鼻果","黄龙病"],"affectedParts":["叶片","新梢","果实"],"growthStages":["新梢期","果实转色期"],"identification":"典型可见叶片斑驳黄化、新梢黄化及红鼻子果；本条只提供疑似筛查，外观不能作为病菌确证。须结合种苗来源、木虱监测和专业检测。","differential":"须与缺锌缺镁等缺素、根系受损和其他黄化区分；观察到木虱不等于已感染黄龙病，不能凭叶黄确诊。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"疑似当日联系属地植保植检机构，按专业要求采样检测并登记上报和回执；停止自行调运疑似种苗、接穗，不自行砍树或喷药处置，由属地机构依法指导处理。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"怀化市农业农村局（转载赣南新农村）；湖北省农业农村厅；重庆市农业农村委员会","sourceVersion":"2023-09-26识别；2025-06-26防控；2020-11-04检疫名单；2026-11-14整理","sourceRef":"识别（不采用原文确诊概率）：http://www.huaihua.gov.cn/nyncj/c108787/202309/73ee08fa777d49c6b8a07f6968730a40.shtml；上报：http://nyt.hubei.gov.cn/zfxxgk/zc_GK2020/qtzdgkwj_GK2020/tz/202506/t20250626_5706990.shtml；检疫：https://nyncw.cq.gov.cn/wsdw/zz/zhfb/zcfg/202312/t20231214_12705874_wap.html","articleId":"","quarantine":true}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='8480b601-d218-5050-85f7-a72a56071075' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黄龙病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8480b601-d218-5050-85f7-a72a56071075' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '42e92816-838a-56ed-a13f-65bf5dad0c28',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"潜叶蛾","diseaseAliases":["柑橘潜叶蛾","柑桔潜叶蛾","绘图虫","鬼画符"],"symptomKeywords":["银白色弯曲隧道","银白色虫道","嫩叶卷缩硬化","潜叶蛾"],"affectedParts":["嫩叶","新梢"],"growthStages":["春梢期","夏梢期","秋梢期"],"identification":"幼虫潜入新梢嫩叶表皮下取食，形成银白色弯曲隧道，新叶卷缩硬化并可脱落；伤口有利于溃疡病侵染。","differential":"与其他潜食性昆虫及叶片擦伤区分，补拍虫道和幼虫，不把所有银白叶斑当潜叶蛾。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"结合本地监测整齐放梢、避免嫩梢参差，使用对应性诱装置监测，保护天敌；资料中的地区虫量和月份不作为当前地块实时虫情。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"达州市达川区农业农村局；农业农村部 / 全国农技推广服务中心","sourceVersion":"2019-07-30；2025-02-28；2026-11-14公开资料整理","sourceRef":"《抓好柑橘潜叶蛾的防治》识别及农业管理段；http://www.dachuan.gov.cn/xxgk-show-93469.html；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='42e92816-838a-56ed-a13f-65bf5dad0c28' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='潜叶蛾'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='42e92816-838a-56ed-a13f-65bf5dad0c28' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1d58446d-d36e-55aa-8cc0-d8560ad66034',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"红蜘蛛","diseaseAliases":["柑橘红蜘蛛","柑桔红蜘蛛","柑橘全爪螨"],"symptomKeywords":["叶正面苍白斑点","果面苍白斑点","红蜘蛛","全爪螨"],"affectedParts":["叶片","枝条","果实"],"growthStages":["生长期","秋梢期"],"identification":"主要危害叶、枝与果实，受害叶片正面和果面出现苍白色斑点；需放大拍摄活动螨体及卵，记录单位叶片螨量。","differential":"与锈螨、蓟马、药害和缺素失绿比较；本条名称指柑橘红蜘蛛，不能凭红色或苍白斑点独立确定螨种。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"定点监测螨体、卵和受害叶果比例，保护捕食螨等天敌，生防释放及投入品相容性由农技人员评估；不照搬历史地区虫口阈值。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"清远市清新区农业农村局；农业农村部 / 全国农技推广服务中心","sourceVersion":"2024-08-09；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农作物病虫情报第九期》柑桔秋梢期病虫害指导意见识别及农业管理段；https://www.qingxin.gov.cn/qyqxnyncj/gkmlpt/content/1/1902/post_1902032.html；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1d58446d-d36e-55aa-8cc0-d8560ad66034' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='红蜘蛛'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1d58446d-d36e-55aa-8cc0-d8560ad66034' AND revision=1 AND status='PUBLISHED';
INSERT INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a74b02a8-6dc5-5ff1-a32e-a6eca55b3fce',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"蚜虫","diseaseAliases":["柑橘蚜虫","柑桔蚜虫"],"symptomKeywords":["嫩梢卷曲","叶面蜜露","煤污","蚜虫","烟煤"],"affectedParts":["嫩梢","嫩叶"],"growthStages":["春梢期","夏梢期","秋梢期"],"identification":"可导致嫩梢卷曲，分泌物污染叶片并诱发烟煤；需补拍梢叶上的成若虫虫群，黄化或卷梢不能单独确定蚜害。","differential":"与木虱、粉蚧等刺吸式害虫比较；本条为蚜虫类群，煤污不能单独证明蚜虫，不据受害症状判定病毒感染。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","measures":"检查嫩梢虫群、保护瓢虫和草蛉等天敌，按属地监测评估处置；调查虫口与煤污范围，避免无虫证据时直接用药。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","source":"清远市清新区农业农村局；农业农村部 / 全国农技推广服务中心","sourceVersion":"2024-08-09；2025-02-28；2026-11-14公开资料整理","sourceRef":"《农作物病虫情报第九期》柑桔秋梢期病虫害指导意见识别及农业管理段；https://www.qingxin.gov.cn/qyqxnyncj/gkmlpt/content/1/1902/post_1902032.html；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='a74b02a8-6dc5-5ff1-a32e-a6eca55b3fce' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚜虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a74b02a8-6dc5-5ff1-a32e-a6eca55b3fce' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8480b601-d218-5050-85f7-a72a56071075' AND revision=2 AND status='PUBLISHED' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.sourceRef'))='识别（不采用原文确诊概率）：http://www.huaihua.gov.cn/nyncj/c108787/202309/73ee08fa777d49c6b8a07f6968730a40.shtml；上报：http://nyt.hubei.gov.cn/zfxxgk/zc_GK2020/qtzdgkwj_GK2020/tz/202506/t20250626_5706990.shtml；检疫：https://nyncw.cq.gov.cn/wsdw/zz/zhfb/zcfg/202312/t20231214_12705874_wap.html';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '4bd6e6b5-e8b9-5a1c-8ef2-f0ad571c85ae',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"霜霉病","diseaseAliases":["葡萄霜霉病"],"symptomKeywords":["霜霉","叶背白霉","白色霉层","霜霉状物","褪绿斑","半透明斑","黄色多角形斑","叶背白色","穗轴变褐"],"affectedParts":["叶片","叶背","花穗","果实","穗轴"],"growthStages":["展叶期","开花期","幼果期","成熟期"],"identification":"叶片出现褪绿斑，部分品种或生长中后期可呈坏死斑；湿度大时病斑叶背出现白色霜霉状物。幼果和花期受害组织可生稀疏白色霉层，穗轴、果实变褐枯死。","differential":"重点核对叶片正反面及湿度条件。白粉病表面粉状层、褐斑病坏死斑、药害和缺素均可能混淆；没有叶背霉层时不能据黄斑直接判定，必要时镜检。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"改善叶幕通风透光、雨后排水和湿度管理；及时清除病果穗及病残体并按当地要求集中处理；适宜地区可采用避雨栽培。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所","sourceVersion":"2020-03-17公开资料；2026-11-14整理","sourceRef":"识别：https://www.baafs.net.cn/ipp/kjsf/kpkt/66f49b2cf2774f198ec1ab04850796db.htm；果穗及农业管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='霜霉病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='4bd6e6b5-e8b9-5a1c-8ef2-f0ad571c85ae' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '3968abdc-b3de-5fe5-9d28-25d909066a92',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"白腐病","diseaseAliases":["葡萄白腐病"],"symptomKeywords":["灰白色小粒点","果柄腐烂","果皮下颗粒","水浸状腐烂","灰白色腐烂","灰白色颗粒","叶缘轮纹","枝皮纵裂"],"affectedParts":["果实","果梗","穗轴","叶片","枝蔓"],"growthStages":["幼果期","转色期","成熟期"],"identification":"果实常从果柄附近开始腐烂并延及整粒，表皮下可见浅褐色颗粒，果面密生灰白色小粒点。叶部多从叶缘扩展为颜色较浅、带轮纹的大斑，部分病组织见小黑点。","differential":"需与果梗变褐、果实干缩但通常无颗粒状物的溃疡类病害区别；炭疽病可见轮纹状黑点及橘红色黏液，灰霉病主要见鼠灰色霉层。冰雹伤、机械损伤及酸腐可并发。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"及时清除病果、病穗及病枝并集中处理，改善架面通风、排水和叶幕结构；采收时剔除病果，避免带入贮运环节。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所","sourceVersion":"2020-03-17公开资料；2026-11-14整理","sourceRef":"识别与农业管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm；叶部鉴别：https://www.baafs.net.cn/ipp/kjsf/kpkt/66f49b2cf2774f198ec1ab04850796db.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白腐病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='3968abdc-b3de-5fe5-9d28-25d909066a92' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'eb8cb4ef-8f27-56bd-a0eb-2ff71db4def7',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"炭疽病","diseaseAliases":["葡萄炭疽病"],"symptomKeywords":["炭疽","轮纹状小黑点","橘红色黏液","桔红色粘液","果面凹陷","粉红色孢子团","成熟果腐烂"],"affectedParts":["果实","果穗","叶片"],"growthStages":["转色期","成熟期"],"identification":"近成熟果实受害较重，果面出现小黑点，有的排列为轮纹，湿润时可见橘红色黏液。北京园林资料描述初期褐色圆形小斑逐渐扩大并略凹陷，潮湿时可见粉红色孢子团。","differential":"区别白腐病的灰白色颗粒和灰霉病的鼠灰色霉层；单纯果实发褐、凹陷或裂果并不能排除日烧、伤害和其他腐烂。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"剪除病果穗与病组织并按当地要求集中处理；合理修剪、通风和水分管理；具备条件时采用避雨栽培及合适时期果穗套袋。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所；北京市园林绿化局","sourceVersion":"2020-03-17植保所资料；2015-08-19园林资料仅取识别；2026-11-14整理","sourceRef":"果实及管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm；初期特征：https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120292.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='eb8cb4ef-8f27-56bd-a0eb-2ff71db4def7' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '200ab2c9-ed35-5cb1-86f9-7e9eb80cc219',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"黑痘病","diseaseAliases":["葡萄黑痘病","鸟眼病","疮痂病"],"symptomKeywords":["鸟眼","灰白色中央","紫褐色边缘","叶片穿孔","凹陷开裂","叶脉梭形斑","灰白色病斑","紫褐色晕圈"],"affectedParts":["嫩叶","叶片","叶脉","新梢","叶柄","幼果","卷须"],"growthStages":["萌芽期","现蕾期","开花期","幼果期"],"identification":"主要侵害绿色幼嫩部位。叶片初生针头大小褐点，扩大后中央灰白、边缘暗褐或紫色，中心可破裂穿孔；叶脉出现凹陷梭形斑，导致扭曲皱缩。新梢、叶柄、卷须可见凹陷开裂病斑。幼果斑中央灰白，外围可有紫褐晕圈。","differential":"需区别绿盲蝽取食后随叶片伸展形成的孔洞、药害及机械伤。应联查嫩梢、叶脉与幼果是否有边缘深色的凹陷病斑；不能仅据穿孔确定黑痘病。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"修剪并清除病枝、病叶和病果，减少再侵染；合理留梢、改善通风和排水，清理越冬病残体并按当地要求处理。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所；北京市园林绿化局","sourceVersion":"2020-03-17植保所资料；2015-08-19园林资料仅取识别；2026-11-14整理","sourceRef":"叶部与鉴别：https://www.baafs.net.cn/ipp/kjsf/kpkt/66f49b2cf2774f198ec1ab04850796db.htm；幼果特征：https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120292.shtml；农业管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黑痘病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='200ab2c9-ed35-5cb1-86f9-7e9eb80cc219' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e63a6423-549c-5017-8a55-44343f3b0516',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"灰霉病","diseaseAliases":["葡萄灰霉病"],"symptomKeywords":["鼠灰色霉层","灰色霉层","灰霉","花穗腐烂","果实软腐","果穗腐烂"],"affectedParts":["花穗","果实","果穗"],"growthStages":["开花期","转色期","成熟期","贮藏期"],"identification":"花期、果实转色至成熟期以及贮藏期均可发生，引起花穗、果实腐烂，受害部位产生鼠灰色霉层为重要线索。","differential":"与白粉病白色粉状层、霜霉病稀疏白色霉层、白腐病灰白颗粒及酸腐病酸味流汁区别；混合感染时需采集病健交界组织复核。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"加强通风和湿度管理，及时剪除病花穗、病果穗及其他病组织并集中处理；收获时剔除病果，避免贮运传播。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所","sourceVersion":"2020-03-17公开资料；2026-11-14整理","sourceRef":"https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='灰霉病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='e63a6423-549c-5017-8a55-44343f3b0516' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'af81c389-e230-57b5-8b78-43535d96bde9',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"白粉病","diseaseAliases":["葡萄白粉病"],"symptomKeywords":["白粉","粉白色霉斑","白色粉状","果面白粉","叶片卷缩","幼果裂口"],"affectedParts":["叶片","新梢","幼果","果实"],"growthStages":["展叶期","幼果期","膨果期"],"identification":"叶片、新梢及幼果受害。叶片起初白色或褪绿小斑，扩大后出现粉白色霉斑，严重时叶片卷缩干枯。幼果果面着生白粉状物，不能正常发育，常出现裂口。","differential":"需与叶背霜霉状物、灰霉病的灰色霉层、喷药残留和自然果粉区别；观察粉层是否与病斑、组织变形相伴。单凭白色覆盖物或裂果不能确诊。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"清除病叶、病枝和病果等病残体，适度修剪、控制过密叶幕并改善通风；记录发病始期及受害部位，避免与生理裂果混淆。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所；北京市园林绿化局","sourceVersion":"2020-03-17植保所资料；2015-08-19园林资料仅取识别；2026-11-14整理","sourceRef":"果实与管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm；叶部特征：https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120292.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='af81c389-e230-57b5-8b78-43535d96bde9' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '88e22df9-5b86-5fda-adbd-e7d7cf7e215a',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"褐斑病","diseaseAliases":["葡萄褐斑病"],"symptomKeywords":["褐色小斑点","黑褐色中央","黄色晕圈","不规则大斑","病叶早落","褐色叶斑"],"affectedParts":["叶片"],"growthStages":["生长期","成熟期","采收后"],"identification":"主要危害叶片，初期出现近圆形、多角形或不规则褐色小斑，逐渐扩大并融合成不规则大斑。中部黑褐、边缘褐色，病健分界明显，部分斑周围有黄色晕圈，后期病叶干枯破裂、早落。","differential":"与霜霉病中后期坏死斑、黑痘病、白腐病及施药后药害区别。联查叶背霉层、嫩梢和果实症状及施药时间；仅叶片黄化或枯边不能判为褐斑病。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"清理病叶和落叶并按当地要求集中处理；适度修剪、改善通风和排水，合理水肥维持树势；记录扩展范围，不把群体施药后同步坏死误判为传染病。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所","sourceVersion":"2020-03-17公开资料；2026-11-14整理","sourceRef":"识别：https://www.baafs.net.cn/ipp/kjsf/kpkt/66f49b2cf2774f198ec1ab04850796db.htm；农业管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='褐斑病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='88e22df9-5b86-5fda-adbd-e7d7cf7e215a' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '0767f024-f31a-532b-83bc-86e29c1b12db',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"穗轴褐枯病","diseaseAliases":["葡萄穗轴褐枯病"],"symptomKeywords":["穗轴褐枯","褐色梭形病斑","花穗变褐","花穗萎蔫","分枝穗轴坏死","花穗枯死"],"affectedParts":["花穗","穗轴","果梗","幼果"],"growthStages":["开花期","幼果期"],"identification":"花期遇阴雨易发生，初期穗轴出现褐色梭形斑并向花穗扩展，使花穗变褐萎蔫枯死。补充资料描述幼穗分枝穗轴水浸状斑扩展后坏死，后期小穗轴易在分枝处折断。","differential":"与花期灰霉病、幼果霜霉病及生理性落花落果区别；查找鼠灰色或白色霉层，并核对发生阶段。不能将所有果梗干枯或成熟期缩果统归此病。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"清除受害花穗和病残体并集中处理，合理叶幕、排水及水肥管理，花期阴雨后加强巡查。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所；北京市园林绿化局","sourceVersion":"2020-03-17植保所资料；2015-08-19园林资料仅取识别；2026-11-14整理","sourceRef":"花期及管理：https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm；分枝穗轴特征：https://yllhj.beijing.gov.cn/ztxx/bjssylcpzlaqjdgl/jsyd/lg/201510/t20151013_120292.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='穗轴褐枯病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='0767f024-f31a-532b-83bc-86e29c1b12db' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'fe66d1b8-fb40-587e-b55a-e5f87d3840e7',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"酸腐病","diseaseAliases":["葡萄酸腐病"],"symptomKeywords":["醋酸味","酸味流汁","果蝇聚集","果袋湿斑","果皮破裂流汁","褐色腐烂"],"affectedParts":["果实","果穗","果梗","穗轴"],"growthStages":["近成熟期","成熟期"],"identification":"近成熟期果粒出现褐色腐烂、组织破裂解体、大量流汁并有醋酸味，病穗周围常有果蝇幼虫、蛹或成虫；套袋果袋下部可见深色湿斑。腐烂汁液流经的果梗、穗轴和其他果粒可继续腐烂。","differential":"按复合腐烂症候识别，不将果蝇等同于单一致病原因。灰霉、白腐、伤口腐烂等可并发；酸味或果蝇单独出现不足以确诊，需结合流汁、伤口和病程。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"及时清除腐烂果穗和落果，避免腐烂汁液污染健康果；改善通风、排水和水分管理，减少裂果与机械损伤，结合农技指导开展果蝇监测。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"北京市农林科学院植物保护研究所","sourceVersion":"2020-03-17公开资料；2026-11-14整理","sourceRef":"https://www.baafs.net.cn/ipp/kjsf/kpkt/15354ee21d0946d0ad211580428b6cc1.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='酸腐病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='fe66d1b8-fb40-587e-b55a-e5f87d3840e7' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e273673d-17f6-543b-8acb-d92db8b5ad4c',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"蓟马","diseaseAliases":["葡萄蓟马"],"symptomKeywords":["花皮果","木栓化疤痕","黄褐色疤痕","细密失绿小点","幼果细小凹陷","叶片卷曲皱缩"],"affectedParts":["幼果","嫩叶","嫩穗"],"growthStages":["展叶期","开花期","幼果期"],"identification":"蓟马锉吸幼果表皮，形成细小凹陷和黄褐色木栓化疤痕，果粒膨大后伤疤仍存；嫩叶可有细密失绿点、卷曲皱缩。","differential":"仅按蓟马类群识别，不从花皮或裂果判定西花蓟马等具体虫种。与绿盲蝽刺伤、药害、擦伤和病斑鉴别，需补拍花穗及嫩叶中的虫体。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"在嫩叶、花穗和幼果期加强虫情巡查与诱捕监测，合理清园、改善通风并保护天敌；诱捕器规格和防治阈值须采用属地方案，不直接套用宁夏数据。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"宁夏农垦信息网；湖北省植物保护总站","sourceVersion":"2026-06-11宁夏幼果期资料；2023-04-23湖北方案（附件8）；2026-11-14整理","sourceRef":"识别：https://www.nxnk.com/nxnk/ngzs/202606/t20260611_1122889.html；综合管理：https://nyt.hubei.gov.cn/bmdt/yw/zbzh/202304/t20230423_4636234.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='e273673d-17f6-543b-8acb-d92db8b5ad4c' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a23462a2-d7d7-5cee-82fa-7ef8c1f5a375',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"绿盲蝽","diseaseAliases":["葡萄绿盲蝽"],"symptomKeywords":["红褐色小点","嫩叶穿孔","褶皱畸形","黑色凹陷斑","新梢长势弱","刺吸嫩梢"],"affectedParts":["嫩叶","新梢","幼果"],"growthStages":["萌芽期","展叶期","幼果期"],"identification":"刺吸嫩梢、新叶及幼果，嫩叶先呈红褐色小点，随叶片扩展形成穿孔、褶皱畸形；幼果刺伤后可生黑色凹陷斑，膨大后开裂、腐烂，新梢抽生迟缓。","differential":"嫩叶穿孔须与黑痘病、机械伤和药害区别。应查虫体、取食点及新生叶连续受害情况；没有虫体证据时保留疑似。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"重点巡查新梢、嫩叶和幼果，结合属地植保方案开展诱捕监测、清园和生境管理，保护天敌；不将其他产区虫口阈值直接作为自动处置依据。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"宁夏农垦信息网；湖北省植物保护总站","sourceVersion":"2026-06-11宁夏幼果期资料；2023-04-23湖北方案（附件8）；2026-11-14整理","sourceRef":"识别：https://www.nxnk.com/nxnk/ngzs/202606/t20260611_1122889.html；综合管理：https://nyt.hubei.gov.cn/bmdt/yw/zbzh/202304/t20230423_4636234.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='绿盲蝽');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a23462a2-d7d7-5cee-82fa-7ef8c1f5a375' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '89cf972a-e5fc-5c9b-872b-f77fa883830c',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"斑叶蝉","diseaseAliases":["葡萄斑叶蝉"],"symptomKeywords":["密集小白点","叶面失绿发白","叶背群集","整叶枯黄","叶片早落"],"affectedParts":["叶片","叶背"],"growthStages":["展叶期","幼果期","生长期"],"identification":"虫体群集叶背吸食汁液，叶片正面出现密集小白点、整体失绿发白，虫量大时叶片枯黄早落，树势减弱。","differential":"与叶螨、蓟马取食斑及营养失调区别；需查看叶背活动虫体。斑叶蝉不等同于斑衣蜡蝉，本条不把其他叶蝉种名并作同义词。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"加强叶背巡查和虫口监测，结合整枝及副梢管理改善通风，合理清理病虫残体并保护天敌；诱捕方案结合当地虫情确定。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"宁夏农垦信息网；湖北省植物保护总站","sourceVersion":"2026-06-11宁夏幼果期资料；2023-04-23湖北方案（附件8）；2026-11-14整理","sourceRef":"识别：https://www.nxnk.com/nxnk/ngzs/202606/t20260611_1122889.html；综合管理：https://nyt.hubei.gov.cn/bmdt/yw/zbzh/202304/t20230423_4636234.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='斑叶蝉');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='89cf972a-e5fc-5c9b-872b-f77fa883830c' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9122ba3b-b3fc-5f21-a16e-4b2a93dd0082',1,'PUBLISHED','{"cropName":"葡萄","cropAliases":["鲜食葡萄","酿酒葡萄","提子"],"diseaseName":"透翅蛾","diseaseAliases":["葡萄透翅蛾"],"symptomKeywords":["褐色虫粪","蛀孔","髓部掏空","枝蔓发黄","枝条易折断","果穗干枯脱落"],"affectedParts":["新梢","枝蔓","结果母枝","叶片","果穗"],"growthStages":["新梢生长期","开花期","幼果期","生长期"],"identification":"幼虫钻蛀一年生新梢和结果母枝，蛀孔处可堆积褐色虫粪、枝内髓部被蛀空；受害枝蔓发黄、叶片萎蔫，果穗干枯脱落，受害大枝易折断。","differential":"与其他蛀干害虫、枝干病害及缺水萎蔫区别；必须核对虫孔、排粪和蛀道，必要时采集幼虫鉴定。仅枝条枯萎不能确定透翅蛾。本条仅供候选识别，不能仅凭单张照片确诊；证据不足时补拍受害部位、记录发生进程并采样交农技人员复核。","measures":"结合修剪检查并处理有虫粪和蛀孔的受害枝，残枝按当地要求集中处理；检查繁殖材料，结合属地方案开展成虫诱捕监测，不提供自行注药或封孔处方。具体用药须另行核对当前有效的葡萄登记、适用对象和标签，由农技人员复核；本条不提供药剂、剂量、混配或安全间隔处方。","source":"宁夏农垦信息网；湖北省植物保护总站","sourceVersion":"2026-06-11宁夏幼果期资料；2023-04-23湖北方案（附件8）；2026-11-14整理","sourceRef":"识别：https://www.nxnk.com/nxnk/ngzs/202606/t20260611_1122889.html；综合管理：https://nyt.hubei.gov.cn/bmdt/yw/zbzh/202304/t20230423_4636234.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='葡萄' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='透翅蛾');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9122ba3b-b3fc-5f21-a16e-4b2a93dd0082' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a101',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"炭疽病","diseaseAliases":["柑橘炭疽病"],"symptomKeywords":["炭疽","同心轮纹","黑色小点","肉红色黏质小点","烫伤状","泪痕型","软腐","落叶","落果"],"affectedParts":["叶片","枝梢","花","果实","果梗","苗木"],"growthStages":["春梢期","幼果期","果实膨大期","采收期","贮藏期"],"identification":"可危害柑橘地上部多个部位。叶片病斑多在叶缘或叶尖，呈浅灰褐色或不规则形，病健交界清楚，病斑上可见同心轮纹排列的黑色小点；高温多湿或树势弱时可出现叶尖向下扩展的烫伤状急性症状。枝梢病斑可呈梭形并伴黑色小粒点，果实可出现凹陷斑、泪痕状病斑或软腐。","differential":"需与砂皮病、疮痂病、灰霉病、日灼、机械伤及药害区分。红色黏质小点、同心轮纹和受害部位组合可作为候选依据，但单一叶斑、落果或腐烂不能确诊；应补拍病健交界、枝梢和果面，并结合病程与近期管理记录采样复核。","measures":"加强冬春清园，剪除病虫枯枝、摘除病果并按属地要求集中处理；合理修剪改善通风透光，均衡水肥、避免偏施氮肥，及时采收并减少采后损伤。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","source":"农业农村部农产品质量安全监管司；平阳县农业局","sourceVersion":"2022-12-28公开指导意见；2014-05-08病害技术资料；2026-11-14整理","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；识别与管理：https://www.zjpy.gov.cn/art/2014/5/8/art_1257318_4714255.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a101' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a102',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"疮痂病","diseaseAliases":["柑橘疮痂病","癞头疤","钉子果"],"symptomKeywords":["疮痂","癞头疤","钉子果","漏斗状","木栓化突起","蜡黄色","果皮粗糙","叶片畸形","果实畸形"],"affectedParts":["嫩叶","枝梢","花器","幼果","果实"],"growthStages":["春梢期","现蕾期","谢花期","生理落果期"],"identification":"主要危害柑橘嫩叶、枝梢和幼果。叶片初期可见油渍状黄色小点，后病斑木栓化，多向叶背突出、叶面凹陷，呈漏斗状；幼果谢花后可出现褐色小点并形成黄褐色木栓化突起，严重时果小、皮厚、畸形或脱落。","differential":"与溃疡病区分时重点看病斑是否只向叶背突出、叶面凹陷以及是否造成叶片畸形；溃疡病常见叶片正反两面隆起并伴黄色晕圈和火山口状开裂。药害、机械伤和砂皮病也可能造成果面粗糙，证据不足时应补拍正反面及幼果近景并采样。","measures":"春季修剪清除病梢、病叶和落叶，保持树冠通风透光；重点保护春梢嫩叶和谢花后的幼果，检查苗木、接穗来源并做好病区隔离。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","source":"平阳县农业局；农业农村部农产品质量安全监管司","sourceVersion":"2014-05-08公开技术资料；2022-12-28绿色防控指导意见；2026-11-14整理","sourceRef":"识别与发生规律：https://www.zjpy.gov.cn/art/2014/5/8/art_1257318_4714255.html；绿色防控：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='疮痂病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a102' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a103',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"砂皮病","diseaseAliases":["树脂病","柑橘砂皮病","柑橘树脂病","黑点病"],"symptomKeywords":["砂皮","树脂病","黑点病","褐色胶质小粒点","褐色小粒点","果皮粗糙","砂质感","泥块状","泪痕状","枝干流胶"],"affectedParts":["果实","果皮","枝干","枝梢","叶片"],"growthStages":["谢花期","定果期","果实膨大期","秋梢期"],"identification":"果面可出现褐色胶质小粒点，病点增多后果皮粗糙并有砂质感，严重时可连成片呈泥块状或泪痕状。树脂病相关症状还可能出现在枝干和枝梢，需结合枝条病斑、流胶、冻伤或机械伤等背景观察。","differential":"果面粗糙或花皮果也可能由疮痂病、溃疡病、药害、蓟马取食或机械擦伤造成；砂皮病候选应关注褐色胶质小粒点及其在果面上的分布。仅凭果面颜色、粗糙或单个斑点不能确诊，需补拍果面微距、枝干和病健交界并采样复核。","measures":"冬春清园，剪除病虫枝、清除枯枝落叶，合理修剪改善通风透光并增强树势；减少冻伤、日灼和机械损伤，做好果园排水及病残体集中处理。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","source":"农业农村部农产品质量安全监管司；怀化市鹤城区农业农村局","sourceVersion":"2022-12-28公开指导意见；2021-11-15绿色防控方案；2026-11-14整理","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；地方方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='砂皮病');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a103' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a104',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"柑橘木虱","diseaseAliases":["木虱","柑桔木虱"],"symptomKeywords":["木虱","嫩梢虫体","黄色若虫","白色蜡质分泌物","蜜露","煤污","新梢受害","黄龙病媒介"],"affectedParts":["嫩梢","嫩叶","叶柄"],"growthStages":["春梢期","夏梢期","秋梢期","放梢期"],"identification":"主要危害柑橘嫩梢和嫩叶，重点观察新梢上的若虫、成虫及白色蜡质分泌物，刺吸后可造成嫩梢生长受阻，并可能伴蜜露和煤污。柑橘木虱是黄龙病的重要传播媒介，发现木虱不等于已经发生黄龙病。","differential":"需与蚜虫、粉虱及其他嫩梢害虫区分，重点补拍嫩梢虫体、蜡质分泌物和受害叶片。木虱只代表媒介虫候选，黄龙病需结合叶片斑驳黄化、树体表现及检测结果判断，不得凭虫体直接确诊黄龙病。","measures":"春夏秋梢期加强嫩梢巡查和监测，统一放梢、清除失管枝梢，使用无病苗木并做好果园间联防；发现疑似黄龙病树应按属地植保植检流程采样、登记并处理，不由AI自行下结论或处置。具体用药须由农技人员依据当前有效登记和标签核对。","source":"连南瑶族自治县人民政府；清远市清新区农业农村局","sourceVersion":"2021-07-12栽培技术；2025-08-28病虫情报；2026-11-14整理","sourceRef":"栽培与媒介说明：https://www.liannan.gov.cn/gzsn/snxx/content/post_1413624.html；秋梢期病虫情报：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2053052.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='柑橘木虱');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a104' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a105',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"锈壁虱","diseaseAliases":["锈蜘蛛","柑橘锈壁虱","柑橘锈蜘蛛"],"symptomKeywords":["锈壁虱","锈蜘蛛","灰尘状黄褐色粉状物","黄褐色粉状物","果皮褐化","果皮粗糙","叶片失绿"],"affectedParts":["果实","果皮","叶片"],"growthStages":["幼果期","果实膨大期","成熟期"],"identification":"主要危害叶片和果实。受害果面可出现灰尘般黄褐色粉状物，后果皮颜色和质地发生变化、表面粗糙；叶片受害可失绿。田间虫体微小，需结合放大观察和果面症状判断。","differential":"果面灰尘、药液残留、砂皮病和日灼均可能造成类似外观；锈壁虱候选需同时观察果面黄褐色粉状物、受害分布及可见虫体，不能以果皮变色单独确诊。","measures":"加强幼果至膨果期果面和叶片巡查，记录虫情空间分布，合理修剪、清园并保护天敌；防治阈值和处置时机采用属地植保方案，不能跨区域直接套用。具体用药须由农技人员依据当前有效登记和标签核对。","source":"怀化市鹤城区农业农村局；清远市清新区农业农村局","sourceVersion":"2021-11-15绿色防控方案；2025-08-28病虫情报；2026-11-14整理","sourceRef":"绿色防控方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml；病虫情报：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2053052.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='锈壁虱');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a105' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a106',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"蚧壳虫","diseaseAliases":["介壳虫","柑橘介壳虫","矢尖蚧"],"symptomKeywords":["蚧壳虫","介壳虫","蜡壳","固定虫体","蜜露","煤污","枝叶衰弱","果面斑驳"],"affectedParts":["枝条","叶片","叶柄","果实"],"growthStages":["春梢期","开花期","生理落果期","果实膨大期"],"identification":"若虫和成虫常附着在枝条、叶片、叶柄或果实表面刺吸汁液，部分种类具有蜡质介壳；受害部位可出现褪绿、枝叶衰弱，排出的蜜露可诱发煤污。仅见煤污不能直接确定具体蚧壳虫种类。","differential":"需与粉虱、蚜虫及真菌性煤污区分，重点补拍虫体、介壳形态、着生部位和蜜露。矢尖蚧是其中一类，不将所有蚧壳虫都自动判定为矢尖蚧，证据不足时保留类群级疑似。","measures":"结合冬春修剪剪除虫枝和过密枝，改善通风透光；清理落叶及病虫残体，保护天敌并开展枝叶和果实监测。具体虫种、发生程度及处置由属地农技人员结合当前登记和标签核对，本条不提供药剂、剂量或安全间隔。","source":"农业农村部农产品质量安全监管司；怀化市鹤城区农业农村局","sourceVersion":"2022-12-28绿色防控指导意见；2021-11-15绿色防控方案；2026-11-14整理","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；地方方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚧壳虫');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a106' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a107',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"柑橘大实蝇","diseaseAliases":["大实蝇","柑橘实蝇","柑桔大实蝇"],"symptomKeywords":["大实蝇","虫果","产卵孔","果实提前变黄","落果","蛆虫","果实腐烂","果汁外流"],"affectedParts":["果实","果皮","果肉"],"growthStages":["果实膨大期","转色期","成熟期"],"identification":"成虫产卵后，幼虫在果实内部取食，受害果可提前变黄、落果、腐烂，剖果或采样时可能发现蛆状幼虫。田间外观与成熟、裂果或其他腐烂原因可能相似，需结合虫果、落果时间及剖果检查。","differential":"不得仅凭提前变黄或落果认定大实蝇；应与自然成熟、机械伤、酸腐病及其他实蝇类区分。发现虫果需要保留样品并按属地植保要求送检，柑橘大实蝇与橘小实蝇不混为同一病虫条目。","measures":"从成虫发生期开展诱捕监测，及时捡拾落果、摘除未落虫果并按属地要求密封闷杀或集中无害化处理；做好区域联防和果园周边寄主果树管理。具体监测和处置以属地植保方案为准，不将单一诱捕数量自动转换为用药建议。","source":"农业农村部农产品质量安全监管司；怀化市鹤城区农业农村局","sourceVersion":"2022-12-28绿色防控指导意见；2021-11-15绿色防控方案；2026-11-14整理","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；地方方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='柑橘大实蝇');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a107' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a108',1,'PUBLISHED','{"cropName":"柑橘","cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"花蕾蛆","diseaseAliases":["柑橘花蕾蛆","柑桔花蕾蛆"],"symptomKeywords":["花蕾蛆","花蕾受害","花蕾畸形","花蕾脱落","花器变褐","幼虫","落花"],"affectedParts":["花蕾","花器","花"],"growthStages":["现蕾期","开花期"],"identification":"主要发生在花蕾和花器，受害花蕾可出现发育异常、变褐、脱落，检查花蕾或花器可能发现幼虫。落花和坐果率下降还可能由低温、营养失衡、灰霉病或其他花期害虫造成。","differential":"花蕾脱落不是花蕾蛆专有症状，需结合受害花蕾剖检、幼虫形态、发生期和园内监测结果，与灰霉病、蓟马及生理性落花区分；未检出虫体时只保留疑似。","measures":"现蕾期加强花蕾抽查和成虫监测，冬春清园、合理修剪并及时清理受害花蕾和残体；花期保护授粉昆虫和天敌，具体防控时机采用属地植保方案，不根据单一落花现象自动建任务或推荐药剂。","source":"怀化市鹤城区农业农村局；清远市清新区农业农村局","sourceVersion":"2021-11-15绿色防控方案；2026-03-10春季管理资料；2026-11-14整理","sourceRef":"绿色防控方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml；春季管理：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2122441.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='柑橘' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='花蕾蛆');
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a108' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'b14f881e-2010-5a8d-a803-9f1c9e0feb5a',1,'PUBLISHED','{"cropName":"枇杷","cropAliases":[],"diseaseName":"炭疽病","diseaseAliases":["枇杷炭疽病"],"symptomKeywords":["淡褐色水渍状","果面凹陷","同心轮纹","黑色小点","中央灰白"],"affectedParts":["果实","叶片","嫩梢","嫁接苗"],"growthStages":[],"identification":"成熟果和嫁接苗易受害。果面先出现淡褐色水渍斑，后凹陷，小黑点呈同心轮纹排列并扩展；叶片病斑近圆形、中央灰白、边缘暗褐，扩大后连片。","differential":"与其他果腐、叶斑病及冻害区分，不凭凹陷或黑点单独确诊。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"浙江省林业局","sourceVersion":"2024-02-20；2026-11-14整理","sourceRef":"http://lyj.zj.gov.cn/art/2024/2/20/art_1466650_59066697.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='b14f881e-2010-5a8d-a803-9f1c9e0feb5a' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='枇杷' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='b14f881e-2010-5a8d-a803-9f1c9e0feb5a' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '4279f5f5-1749-55cc-92e6-f219fbf537fa',1,'PUBLISHED','{"cropName":"枇杷","cropAliases":[],"diseaseName":"黄毛虫","diseaseAliases":["枇杷黄毛虫","枇杷瘤蛾"],"symptomKeywords":["食芽","嫩叶缺刻","仅剩叶脉","叶背主脉结茧","枝干虫茧"],"affectedParts":["芽","嫩叶","老叶","嫩茎","花","果实"],"growthStages":[],"identification":"幼虫取食芽和嫩叶，严重时危害老叶、嫩茎皮和花果，叶片可仅剩叶脉；老熟幼虫可在叶背主脉或枝干结茧。","differential":"与舟蛾、其他食叶幼虫区分；只有缺刻不足以确定虫种，须观察虫体及虫茧。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"巡查新梢叶面、叶背主脉和枝干，做好个人防护后清理虫茧和群集虫叶；保护寄生蜂等天敌，不徒手接触毛虫。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"浙江省林业局","sourceVersion":"2024-02-20；2026-11-14整理","sourceRef":"http://lyj.zj.gov.cn/art/2024/2/20/art_1466650_59066697.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='4279f5f5-1749-55cc-92e6-f219fbf537fa' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='枇杷' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黄毛虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='4279f5f5-1749-55cc-92e6-f219fbf537fa' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '38af7d0a-ce4a-5c3a-9d8c-da4f4a675151',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"炭疽病","diseaseAliases":["茶炭疽病","茶树炭疽病"],"symptomKeywords":["暗绿色水渍","叶尖病斑","灰白色大斑","黑色细小粒点","病健分界明显"],"affectedParts":["成叶","老叶"],"growthStages":[],"identification":"成叶和老叶叶缘或叶尖先现暗绿色水渍斑，转黄褐色后形成灰白色不规则大斑，散生黑色细小粒点，病健界限明显。","differential":"与轮斑、其他叶枯及日灼肥害区别。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='38af7d0a-ce4a-5c3a-9d8c-da4f4a675151' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='38af7d0a-ce4a-5c3a-9d8c-da4f4a675151' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '14c03aa9-ad89-5bde-8f65-d1c2a625335f',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"茶饼病","diseaseAliases":["饼病","茶树茶饼病"],"symptomKeywords":["透明斑","正面凹陷","背面突起","疱斑","灰白色粉末","饼状枯斑"],"affectedParts":["嫩叶","嫩梢","叶柄"],"growthStages":[],"identification":"嫩叶初现淡黄或淡红近圆形透明斑，随后正面凹陷、叶背突起成疱斑，覆灰白或粉红粉末，后成有灰白边圈的淡褐枯斑。","differential":"与虫瘿、其他叶斑及机械损伤区分，结合正反面隆起和粉层观察。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康茶苗；分批勤采、适期修剪并清除枯枝，改善通风，均衡施肥。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='14c03aa9-ad89-5bde-8f65-d1c2a625335f' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='茶饼病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='14c03aa9-ad89-5bde-8f65-d1c2a625335f' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '8010d9f7-09dd-526c-87b4-02a0343da230',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"小绿叶蝉","diseaseAliases":["茶小绿叶蝉","假眼小绿叶蝉"],"symptomKeywords":["芽叶失绿","芽叶老化","顶部枯焦","茶芽不发"],"affectedParts":["嫩茎","嫩叶","芽"],"growthStages":[],"identification":"若虫和成虫刺吸嫩茎嫩叶，芽叶失绿、老化；严重时顶部芽叶枯焦，茶芽不发。","differential":"按茶园小绿叶蝉类群提供候选依据，俗名不代表所有分类学名称等同；与干旱、螨害和肥害区分，需拍清活动虫体。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"适时分批采摘并监测嫩梢虫量，保护蜘蛛及寄生蜂；诱虫板依属地方案设置，避免无差别过量诱杀。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='8010d9f7-09dd-526c-87b4-02a0343da230' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='小绿叶蝉'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8010d9f7-09dd-526c-87b4-02a0343da230' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'acf4d40f-2842-53cd-9196-90aee43089ca',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"尺蠖类","diseaseAliases":["茶尺蠖","灰茶尺蠖","茶树尺蠖类"],"symptomKeywords":["取食嫩叶","取食成叶","叶片吃光","新梢嫩皮被食"],"affectedParts":["嫩叶","成叶","新梢","嫩皮"],"growthStages":[],"identification":"以幼虫取食嫩叶和成叶，大发生可将老叶、新梢嫩皮等啃食严重。","differential":"茶尺蠖和灰茶尺蠖按尺蠖类群收录，不视作同一虫种；与茶毛虫及其他食叶虫区分，需拍清幼虫。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"保护寄生蜂和蜘蛛，结合茶园秋季管理降低越冬蛹基数；在专业指导下按目标虫种选用信息素监测或定时灯诱。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='acf4d40f-2842-53cd-9196-90aee43089ca' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='尺蠖类'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='acf4d40f-2842-53cd-9196-90aee43089ca' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'ac67f34b-6cec-5502-98e8-33445e4fe459',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"黑刺粉虱","diseaseAliases":["茶黑刺粉虱","黑剌粉虱"],"symptomKeywords":["叶背吸汁","分泌蜜露","煤烟","叶背粉虱"],"affectedParts":["叶背","叶片"],"growthStages":[],"identification":"幼虫主要在叶背吸食汁液，分泌物可诱发煤烟病。","differential":"煤烟和黄叶不是专有症状，需观察叶背虫体；与蚜虫、蚧壳虫及其他粉虱区分。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"适时修剪疏枝、清园并促进通风，检查叶背；诱虫板监测结合成虫发生期和天敌保护执行。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='ac67f34b-6cec-5502-98e8-33445e4fe459' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黑刺粉虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='ac67f34b-6cec-5502-98e8-33445e4fe459' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'd174a543-44fa-536c-92c1-4c53502dd675',1,'PUBLISHED','{"cropName":"茶树","cropAliases":["茶叶","茶","茶园"],"diseaseName":"茶橙瘿螨","diseaseAliases":["茶橙瘿螨害"],"symptomKeywords":["失去光泽","主脉发红","叶背褐色锈斑","芽叶僵化","芽叶萎缩"],"affectedParts":["嫩叶","成叶","叶背","芽"],"growthStages":[],"identification":"幼螨、若螨和成螨刺吸嫩叶与成叶；叶失光泽、叶色变浅，叶面主脉发红，叶背有褐锈斑，芽叶萎缩僵化。","differential":"与其他茶树螨、蓟马、日灼及缺素比较，需要放大观察螨体，不凭锈斑确定螨种。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"及时分批采摘，记录芽叶和叶背受害范围，保护捕食性天敌，按属地指导处理受害枝叶。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"杭州市临安区农业农村局；全国农业技术推广服务中心","sourceVersion":"2020-08-19识别；2023-03-03防控；2026-11-14整理","sourceRef":"识别：https://www.linan.gov.cn/art/2020/8/19/art_1367635_54614589.html；管理：http://www.moa.gov.cn/ztzl/2023cg/jszd_29356/202303/t20230306_6422312.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='d174a543-44fa-536c-92c1-4c53502dd675' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='茶树' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='茶橙瘿螨'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='d174a543-44fa-536c-92c1-4c53502dd675' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1e9c2995-ace4-5070-a4ce-e3e84b5895f0',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"病毒病","diseaseAliases":["百香果病毒病","疑似病毒病"],"symptomKeywords":["浅黄色斑驳","花叶","叶片反卷","果实畸形硬化","果皮变厚","果腔缩小","果皮花斑"],"affectedParts":["叶片","果实"],"growthStages":[],"identification":"可见叶片浅黄斑驳、皱缩或反卷，果实小且畸形硬化、果皮增厚及果腔缩小，部分病果果皮有花斑。","differential":"按疑似病毒性症候收录，不凭照片指定木质化病毒、花叶病毒等病原；与蓟马、药害、缺素区别，需采样检测。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用经检测健康种苗；修剪工具保持清洁并规范消毒，监测蚜虫、蓟马，疑似病株先标记、避免取穗繁殖并请专业人员检测后处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1e9c2995-ace4-5070-a4ce-e3e84b5895f0' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='病毒病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1e9c2995-ace4-5070-a4ce-e3e84b5895f0' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7441dc40-a845-5b79-be00-4dcf2c638e10',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"茎基腐病","diseaseAliases":["百香果茎基腐病"],"symptomKeywords":["缺水黄化","茎基深褐","皮层裂痕","茎基腐烂","粉白色病原物","环绕主蔓"],"affectedParts":["茎基部","主蔓","侧蔓","叶片"],"growthStages":[],"identification":"初期叶片缺水黄化、植株萎蔫，茎基或主侧蔓变深褐，皮层开裂、变软腐烂，可见粉白色病原物，扩展可环绕主蔓致死。","differential":"与疫病、根腐、机械损伤和涝害区别；不把茎基腐病名称直接等同于单一病原，需检查基部并采样。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选健康种苗，保持茎基稳固、减少伤口，防止基部积水和全园漫灌，巡查标记病株并由专业人员确定清理范围。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7441dc40-a845-5b79-be00-4dcf2c638e10' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='茎基腐病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7441dc40-a845-5b79-be00-4dcf2c638e10' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7c3dec65-e053-55c0-ab1f-639f6ec2661a',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"炭疽病","diseaseAliases":["百香果炭疽病"],"symptomKeywords":["淡褐色小圆斑","边缘深褐","中央浅褐","黑色小粒点","黑褐色凹陷"],"affectedParts":["果实","叶片","茎蔓"],"growthStages":[],"identification":"果面初生淡褐小圆斑，扩大变褐至深褐；叶缘半圆或近圆斑，边深褐、中央浅褐并有黑小粒点；茎蔓可有黑褐凹陷水渍斑。","differential":"与褐斑病、疫病和虫伤果腐比较，必要时采样。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7c3dec65-e053-55c0-ab1f-639f6ec2661a' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7c3dec65-e053-55c0-ab1f-639f6ec2661a' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '66b45f1a-6b6e-594a-95ed-e08f834f70ae',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"疫病","diseaseAliases":["百香果疫病","果疫病"],"symptomKeywords":["水渍状病斑","白色霉状物","软化腐烂","茎蔓褐色","整株凋萎"],"affectedParts":["果实","叶片","茎蔓","根茎"],"growthStages":[],"identification":"水渍斑为主要特征，茎蔓褐变、叶萎凋，潮湿时有白霉；果实褐色近圆或不规则斑，后软化腐烂并生白霉，严重时根茎腐烂、全株凋萎。","differential":"与茎基腐、其他果腐及涝害区分；同株可能多部位或混合发病，水渍斑不能单独确诊。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选健康种苗，合理密度、保持排水，雨季及时降湿，清除病果病叶并按属地要求处理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='66b45f1a-6b6e-594a-95ed-e08f834f70ae' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='疫病'));
