INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '43ae8a03-08f3-50ac-b3b5-cf49786c73ad',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"褐斑病","diseaseAliases":["百香果褐斑病"],"symptomKeywords":["圆形褐色斑点","轮纹状扩大","中心浅褐","病斑黄晕"],"affectedParts":["叶片","果实"],"growthStages":[],"identification":"叶片和果实初现圆形褐斑，病斑呈轮纹状扩大，中心组织转浅褐色，病斑常带黄晕。","differential":"与炭疽、疫病及药害区分，结合轮纹、斑缘及病程采样鉴别。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='43ae8a03-08f3-50ac-b3b5-cf49786c73ad' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='褐斑病'));
