INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '6aa90e6e-edb5-5329-b631-586d8590ce85',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"蚜虫","diseaseAliases":["百香果蚜虫"],"symptomKeywords":["叶背卷缩","嫩梢扭曲成团","蜜露","煤烟病"],"affectedParts":["叶背","嫩梢","叶片"],"growthStages":[],"identification":"叶背不规则卷缩，嫩梢叶片扭曲成团，虫体排泄蜜露可诱发煤烟病。","differential":"与蓟马、病毒病及其他刺吸虫区分；发现媒介虫不代表已感染病毒。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"巡查叶背和嫩梢，保护天敌，采用适宜诱虫板监测并清理虫害残体；疑似病毒症状另行采样。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='6aa90e6e-edb5-5329-b631-586d8590ce85' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚜虫'));
