INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '764b3d4c-0c5e-5f17-8468-20bfba3c140e',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"蓟马","diseaseAliases":["百香果蓟马"],"symptomKeywords":["叶片变形","皱缩卷曲","落花","落果","果面创痕"],"affectedParts":["叶片","花器","果实"],"growthStages":[],"identification":"叶片变形皱缩卷曲，可与病毒症状相似；花器受害造成落花落果，果面受害留下创痕。","differential":"与病毒、擦伤、螨害区分，需拍清花内或嫩部细小虫体；不凭创痕判定具体蓟马种。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"清理枯枝落叶，结合蓝色粘虫板监测并保护授粉昆虫，记录花器及幼果虫量。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='764b3d4c-0c5e-5f17-8468-20bfba3c140e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马'));
