INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '75c3a000-5522-5c47-97fd-70081ddf9fc0',1,'PUBLISHED','{"cropName":"百香果","cropAliases":["西番莲","鸡蛋果"],"diseaseName":"橘小实蝇","diseaseAliases":["桔小实蝇","百香果橘小实蝇"],"symptomKeywords":["产卵孔","果皮凸起","未熟脱落"],"affectedParts":["果实"],"growthStages":[],"identification":"果皮可出现产卵孔或凸起，果实可未熟脱落。","differential":"与其他实蝇、蛀果虫和生理落果区分；照片只能提示疑似，需诱捕成虫或采集幼虫鉴定，不与柑橘大实蝇混用。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"及时收集虫果和落果并按当地要求集中处理，结合属地方案开展诱捕监测；跨区调运另行核查检疫要求。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省市场监督管理局；福建省种植业技术推广总站、福建省农业科学院果树研究所","sourceVersion":"DB35/T 1858—2019；2019-09-11发布；附录B；2026-11-14整理","sourceRef":"https://dbba.sacinfo.org.cn/portal/download/bad3fd8883bf699037687e2bbedb2adcda6d3d317ebb1485a186d3d3792552d0","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='75c3a000-5522-5c47-97fd-70081ddf9fc0' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='百香果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='橘小实蝇'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='75c3a000-5522-5c47-97fd-70081ddf9fc0' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '5265a226-d039-5b37-9043-e552ac61b3fb',1,'PUBLISHED','{"cropName":"荔枝","cropAliases":[],"diseaseName":"霜疫霉病","diseaseAliases":["荔枝霜疫霉病"],"symptomKeywords":["叶尖褐斑","叶缘不规则褐斑","花穗变褐","稀疏霜状霉层","花穗枯萎"],"affectedParts":["嫩叶","花穗"],"growthStages":[],"identification":"嫩叶叶尖、叶缘出现褐色不规则斑并向主脉扩展；花穗变褐，可见稀疏霜状霉层，严重时花穗枯萎脱落。","differential":"与炭疽、花穗枯死及其他霉层区别；本条只适用荔枝，不向龙眼自动扩展。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"广州市农业环境与植物保护总站","sourceVersion":"2026-03-02花期病虫监测明白纸；2026-11-14整理","sourceRef":"http://nyncj.gz.gov.cn/hd/zsk/zz/content/post_10706219.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='5265a226-d039-5b37-9043-e552ac61b3fb' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='荔枝' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='霜疫霉病'));
