INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'b766f96f-fc98-5e9b-add1-3475a72cb638',1,'PUBLISHED','{"cropName":"荔枝","cropAliases":[],"diseaseName":"荔枝蝽","diseaseAliases":["荔枝蝽象","荔枝蝽蟓"],"symptomKeywords":["嫩枝褐变","花穗受害","落花","褐色灼伤状","臭液"],"affectedParts":["嫩枝","嫩叶","花穗"],"growthStages":[],"identification":"成虫和若虫刺吸嫩枝、花穗汁液致褐变落花；分泌臭液接触嫩叶花穗可产生褐色灼伤状斑。","differential":"与药害、日灼及其他蝽类区分，需拍清虫体、卵块，避免臭液接触皮肤或眼睛。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"保护平腹小蜂等天敌，监测成若虫和卵块，做好防护后人工摘除确认的卵块；花期保护传粉昆虫。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"广州市农业环境与植物保护总站","sourceVersion":"2026-03-02花期病虫监测明白纸；2026-11-14整理","sourceRef":"http://nyncj.gz.gov.cn/hd/zsk/zz/content/post_10706219.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='b766f96f-fc98-5e9b-add1-3475a72cb638' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='荔枝' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='荔枝蝽'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='b766f96f-fc98-5e9b-add1-3475a72cb638' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'f305aaee-25cf-5cd7-beb3-abef57efc8cc',1,'PUBLISHED','{"cropName":"荔枝","cropAliases":[],"diseaseName":"荔枝瘿螨","diseaseAliases":["毛毡病","荔枝毛毡病"],"symptomKeywords":["叶背毛毡","叶面凸起","叶片扭曲","褐色绒毛","花穗膨大"],"affectedParts":["嫩叶","叶背","花穗"],"growthStages":[],"identification":"叶背呈毛毡状凹陷、叶面凸起，叶片扭曲畸形，老熟后叶背绒毛变褐；花穗可膨大扭曲并长绒毛。","differential":"毛毡为虫害症候，不当作真菌霉层；与叶瘿蚊虫瘿、病斑及其他螨害区分，放大观察。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"广州市农业环境与植物保护总站","sourceVersion":"2026-03-02花期病虫监测明白纸；2026-11-14整理","sourceRef":"http://nyncj.gz.gov.cn/hd/zsk/zz/content/post_10706219.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='f305aaee-25cf-5cd7-beb3-abef57efc8cc' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='荔枝' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='荔枝瘿螨'));
