INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9d01467b-d611-5d76-99e8-dcf63f1ded74',1,'PUBLISHED','{"cropName":"荔枝","cropAliases":[],"diseaseName":"叶瘿蚊","diseaseAliases":["荔枝叶瘿蚊","荔枝瘿蚊"],"symptomKeywords":["水渍状点痕","瘤状虫瘿","两面突起","扭曲干焦","干枯穿孔"],"affectedParts":["嫩叶"],"growthStages":[],"identification":"幼虫侵入嫩叶，初现水渍点痕，后向两面突起成瘤状虫瘿；严重时叶片扭曲干焦，后期病部干枯穿孔。","differential":"与瘿螨毛毡、其他虫瘿及叶斑穿孔区别，需要观察瘿内虫体。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"广州市农业环境与植物保护总站","sourceVersion":"2026-03-02花期病虫监测明白纸；2026-11-14整理","sourceRef":"http://nyncj.gz.gov.cn/hd/zsk/zz/content/post_10706219.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9d01467b-d611-5d76-99e8-dcf63f1ded74' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='荔枝' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='叶瘿蚊'));
