INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'bb1b6d96-771a-54da-8042-de9e1d6f5bf2',1,'PUBLISHED','{"cropName":"荔枝","cropAliases":[],"diseaseName":"蒂蛀虫","diseaseAliases":["荔枝蒂蛀虫"],"symptomKeywords":["果蒂蛀孔","核肉间虫道","果内虫粪","蛀果脱落"],"affectedParts":["果实","果蒂"],"growthStages":[],"identification":"幼虫可从果蒂处蛀入，在果核与果肉间钻蛀取食，形成虫道及虫粪，果实可脱落、继发腐烂。","differential":"识别特征依据海关公开检索摘要，全文访问受限；本条仅作疑似蛀果候选，与其他蛀果虫区分，须剖果取样鉴定。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"检查果蒂并收集虫果落果，按属地要求集中处理，选健康苗、清理残体并保护寄生蜂；套袋和诱捕依当地技术指导实施。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"宁波海关科普检索摘要；香港渔农自然护理署","sourceVersion":"2026-07-30识别摘要；2025-04综合管理全文；2026-11-14整理","sourceRef":"识别摘要：http://gdfs.customs.gov.cn/ningbo_customs/2026-07/30/article_2026073102575118227.html；管理：https://www.afcd.gov.hk/english/agriculture/agr_useful/agr_useful_com/files/Pest_and_Diseases_Management_13b.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='bb1b6d96-771a-54da-8042-de9e1d6f5bf2' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='荔枝' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蒂蛀虫'));
