INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '87ce3140-7a0d-5411-8e98-3ffef52ff740',1,'PUBLISHED','{"cropName":"龙眼","cropAliases":["桂圆"],"diseaseName":"荔枝蝽","diseaseAliases":["荔枝蝽象","荔枝蝽蟓"],"symptomKeywords":["嫩枝褐变","花穗受害","臭液","蝽象卵块"],"affectedParts":["嫩枝","花穗","叶片"],"growthStages":[],"identification":"荔枝蝽为荔枝和龙眼共同重要害虫，成若虫在树上取食、交配和产卵，应检查嫩梢、花穗及卵块。","differential":"枝梢受害或臭液不是充分确诊证据，需观察虫体；龙眼条目只标记该共同害虫，不继承荔枝专属病害。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"监测成若虫和卵块，做好防护后人工摘除确认卵块，保护平腹小蜂等天敌，合理修剪改善通透。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省植保总站；香港渔农自然护理署","sourceVersion":"2021-04-19识别与监测；2025-04综合管理；2026-11-14整理","sourceRef":"http://nynct.fujian.gov.cn/ztzl/bcfsyfk/202104/t20210419_5577905.htm；https://www.afcd.gov.hk/english/agriculture/agr_useful/agr_useful_com/files/Pest_and_Diseases_Management_13b.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='87ce3140-7a0d-5411-8e98-3ffef52ff740' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='龙眼' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='荔枝蝽'));
