INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '8c2d13b5-1991-5df1-8889-d8ef55da6140',1,'PUBLISHED','{"cropName":"龙眼","cropAliases":["桂圆"],"diseaseName":"角颊木虱","diseaseAliases":["龙眼角颊木虱","龙眼木虱"],"symptomKeywords":["嫩叶木虱","新梢木虱","低龄若虫","嫩叶受害"],"affectedParts":["嫩叶","新梢"],"growthStages":[],"identification":"龙眼嫩叶、新梢的主要害虫之一，抽梢期需检查成虫及若虫；该来源提供虫情与危害部位，不提供仅凭斑点确定种类的依据。","differential":"需拍清木虱虫体并由专业人员鉴定；与荔枝瘿螨、叶瘿蚊和其他刺吸害虫区分，发现木虱不能直接判定鬼帚病。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"选用健康种苗，合理水肥和修剪，保持排水及通风；清理病虫残体和落果并按属地要求处理，保护天敌，结合监测确定处置。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省植保总站；香港渔农自然护理署","sourceVersion":"2021-04-19识别与监测；2025-04综合管理；2026-11-14整理","sourceRef":"http://nynct.fujian.gov.cn/ztzl/bcfsyfk/202104/t20210419_5577905.htm；https://www.afcd.gov.hk/english/agriculture/agr_useful/agr_useful_com/files/Pest_and_Diseases_Management_13b.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='8c2d13b5-1991-5df1-8889-d8ef55da6140' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='龙眼' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='角颊木虱'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8c2d13b5-1991-5df1-8889-d8ef55da6140' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '8f18fc6d-ca98-5c65-9e4f-97fea10e9c9d',1,'PUBLISHED','{"cropName":"龙眼","cropAliases":["桂圆"],"diseaseName":"木毒蛾","diseaseAliases":["龙眼木毒蛾"],"symptomKeywords":["幼虫啃食","叶片缺刻","花穗被食","果穗被食"],"affectedParts":["叶片","花穗","果穗"],"growthStages":[],"identification":"幼虫啃食龙眼、荔枝叶片、花穗及果穗，监测低龄幼虫和局部群集受害点。","differential":"需拍清虫体，不能把所有毛虫统一确定为木毒蛾；与尺蛾、卷叶蛾及其他食叶虫区分。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"巡查幼虫发生点，做好个人防护后清理确认的虫害残体，保护天敌，不徒手接触毛虫。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省植保总站；香港渔农自然护理署","sourceVersion":"2021-04-19识别与监测；2025-04综合管理；2026-11-14整理","sourceRef":"http://nynct.fujian.gov.cn/ztzl/bcfsyfk/202104/t20210419_5577905.htm；https://www.afcd.gov.hk/english/agriculture/agr_useful/agr_useful_com/files/Pest_and_Diseases_Management_13b.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='8f18fc6d-ca98-5c65-9e4f-97fea10e9c9d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='龙眼' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='木毒蛾'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8f18fc6d-ca98-5c65-9e4f-97fea10e9c9d' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'caf80230-0467-5c40-9396-f0bdd58e83c7',1,'PUBLISHED','{"cropName":"龙眼","cropAliases":["桂圆"],"diseaseName":"蒂蛀虫","diseaseAliases":["荔枝蒂蛀虫","龙眼蒂蛀虫"],"symptomKeywords":["果蒂蛀孔","果内虫道","果内虫粪","蛀果脱落"],"affectedParts":["果实","果蒂"],"growthStages":[],"identification":"香港渔农自然护理署将荔枝蒂蛀虫列为龙眼、荔枝常见害虫；需检查果蒂和剖果查找蛀道、虫体及虫粪。","differential":"该龙眼条目为蛀果候选线索，具体种类须采虫鉴定，不以果实腐烂直接确定蒂蛀虫。本条为候选识别依据，不是现场确诊；补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气及近期用药，证据不足或加重时采样交农技人员复核。","measures":"及时清理虫果和落果，保护寄生蜂，修剪改善通风，诱捕监测依当地专业方案执行。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"福建省植保总站；香港渔农自然护理署","sourceVersion":"2021-04-19识别与监测；2025-04综合管理；2026-11-14整理","sourceRef":"http://nynct.fujian.gov.cn/ztzl/bcfsyfk/202104/t20210419_5577905.htm；https://www.afcd.gov.hk/english/agriculture/agr_useful/agr_useful_com/files/Pest_and_Diseases_Management_13b.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='caf80230-0467-5c40-9396-f0bdd58e83c7' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='龙眼' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蒂蛀虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='caf80230-0467-5c40-9396-f0bdd58e83c7' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='1d58446d-d36e-55aa-8cc0-d8560ad66034' AND revision=2 AND status='PUBLISHED' AND payload_json=CAST('{"source":"清远市清新区农业农村局；农业农村部 / 全国农技推广服务中心；云浮市农业农村局","cropName":"柑橘","measures":"定点监测螨体、卵和受害叶果比例，保护捕食螨等天敌，生防释放及投入品相容性由农技人员评估；不照搬历史地区虫口阈值。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","articleId":"","sourceRef":"《农作物病虫情报第九期》柑桔秋梢期病虫害指导意见识别及农业管理段；https://www.qingxin.gov.cn/qyqxnyncj/gkmlpt/content/1/1902/post_1902032.html；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm；蜜柚/柚类适用依据：https://www.yunfu.gov.cn/nyncj/zdht/syjs/content/post_377939.html","quarantine":false,"cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"红蜘蛛","differential":"与锈螨、蓟马、药害和缺素失绿比较；本条名称指柑橘红蜘蛛，不能凭红色或苍白斑点独立确定螨种。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","growthStages":["生长期","秋梢期"],"affectedParts":["叶片","枝条","果实"],"sourceVersion":"2024-08-09；2025-02-28；2026-11-14公开资料整理；2019-04-23柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘红蜘蛛","柑桔红蜘蛛","柑橘全爪螨"],"identification":"主要危害叶、枝与果实，受害叶片正面和果面出现苍白色斑点；需放大拍摄活动螨体及卵，记录单位叶片螨量。","symptomKeywords":["叶正面苍白斑点","果面苍白斑点","红蜘蛛","全爪螨"]}' AS JSON);
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='42e92816-838a-56ed-a13f-65bf5dad0c28' AND revision=2 AND status='PUBLISHED' AND payload_json=CAST('{"source":"达州市达川区农业农村局；农业农村部 / 全国农技推广服务中心","cropName":"柑橘","measures":"结合本地监测整齐放梢、避免嫩梢参差，使用对应性诱装置监测，保护天敌；资料中的地区虫量和月份不作为当前地块实时虫情。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","articleId":"","sourceRef":"《抓好柑橘潜叶蛾的防治》识别及农业管理段；http://www.dachuan.gov.cn/xxgk-show-93469.html；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm；蜜柚/柚类适用依据：http://www.dachuan.gov.cn/xxgk-show-93469.html","quarantine":false,"cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"潜叶蛾","differential":"与其他潜食性昆虫及叶片擦伤区分，补拍虫道和幼虫，不把所有银白叶斑当潜叶蛾。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","growthStages":["春梢期","夏梢期","秋梢期"],"affectedParts":["嫩叶","新梢"],"sourceVersion":"2019-07-30；2025-02-28；2026-11-14公开资料整理；2019-07-30柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘潜叶蛾","柑桔潜叶蛾","绘图虫","鬼画符"],"identification":"幼虫潜入新梢嫩叶表皮下取食，形成银白色弯曲隧道，新叶卷缩硬化并可脱落；伤口有利于溃疡病侵染。","symptomKeywords":["银白色弯曲隧道","银白色虫道","嫩叶卷缩硬化","潜叶蛾"]}' AS JSON);
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9627ea6f-d3a2-5d34-928f-ad1dc9312869' AND revision=2 AND status='PUBLISHED' AND payload_json=CAST('{"source":"安远县人民政府；农业农村部 / 全国农技推广服务中心；尤溪县农业农村局","cropName":"柑橘","measures":"减少雨露未干时的穿园操作，合理控梢、保持通风并监测潜叶蛾伤口；发现疑似及时联系属地植保植检机构，核查繁殖材料来源和调运要求。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","articleId":"","sourceRef":"《柑橘溃疡病的发生与防治》识别及农业管理段；https://www.ay.gov.cn/ayzf/c138678depunvpuhgqd/202606/0746640db686465c960186998119811c.shtml；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm；蜜柚/柚类适用依据：http://www.fjyx.gov.cn/ztzl/snxx/bcqb/202603/t20260316_2194808.htm","quarantine":false,"cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"溃疡病","differential":"与疮痂、机械伤和潜叶蛾伤口比较，双面隆起及火山口裂纹是重点；确证需专业检测。是否属属地补充检疫对象及调运要求由植检机构核定。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","growthStages":["新梢期","幼果期","果实膨大期"],"affectedParts":["叶片","枝梢","果实"],"sourceVersion":"2026-06-01；2025-02-28；2026-11-14公开资料整理；2026-03-16柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘溃疡病"],"identification":"叶背初生淡黄色油浸状小点，后叶正反面同时隆起，形成灰褐色木栓化病斑，中心火山口状凹陷开裂、周围黄色晕环；枝梢斑更突起，果实斑更大且木栓化明显。","symptomKeywords":["火山口状开裂","正反两面隆起","木栓化病斑","油浸状小点","黄色晕环"]}' AS JSON);
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a101' AND revision=2 AND status='PUBLISHED' AND payload_json=CAST('{"source":"农业农村部农产品质量安全监管司；平阳县农业局；云浮市农业农村局","cropName":"柑橘","measures":"加强冬春清园，剪除病虫枯枝、摘除病果并按属地要求集中处理；合理修剪改善通风透光，均衡水肥、避免偏施氮肥，及时采收并减少采后损伤。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","articleId":"","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；识别与管理：https://www.zjpy.gov.cn/art/2014/5/8/art_1257318_4714255.html；蜜柚/柚类适用依据：https://www.yunfu.gov.cn/nyncj/zdht/syjs/content/post_377939.html","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"炭疽病","differential":"需与砂皮病、疮痂病、灰霉病、日灼、机械伤及药害区分。红色黏质小点、同心轮纹和受害部位组合可作为候选依据，但单一叶斑、落果或腐烂不能确诊；应补拍病健交界、枝梢和果面，并结合病程与近期管理记录采样复核。","growthStages":["春梢期","幼果期","果实膨大期","采收期","贮藏期"],"affectedParts":["叶片","枝梢","花","果实","果梗","苗木"],"sourceVersion":"2022-12-28公开指导意见；2014-05-08病害技术资料；2026-11-14整理；2019-04-23柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘炭疽病"],"identification":"可危害柑橘地上部多个部位。叶片病斑多在叶缘或叶尖，呈浅灰褐色或不规则形，病健交界清楚，病斑上可见同心轮纹排列的黑色小点；高温多湿或树势弱时可出现叶尖向下扩展的烫伤状急性症状。枝梢病斑可呈梭形并伴黑色小粒点，果实可出现凹陷斑、泪痕状病斑或软腐。","symptomKeywords":["炭疽","同心轮纹","黑色小点","肉红色黏质小点","烫伤状","泪痕型","软腐","落叶","落果"]}' AS JSON);
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a105' AND revision=2 AND status='PUBLISHED' AND payload_json=CAST('{"source":"怀化市鹤城区农业农村局；清远市清新区农业农村局；农业农村部门户柑橘专栏","cropName":"柑橘","measures":"加强幼果至膨果期果面和叶片巡查，记录虫情空间分布，合理修剪、清园并保护天敌；防治阈值和处置时机采用属地植保方案，不能跨区域直接套用。具体用药须由农技人员依据当前有效登记和标签核对。","articleId":"","sourceRef":"绿色防控方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml；病虫情报：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2053052.html；蜜柚/柚类适用依据：https://www.moa.gov.cn/ztzl/gjcxzl/jkxf/200810/t20081030_1163931.htm","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"锈壁虱","differential":"果面灰尘、药液残留、砂皮病和日灼均可能造成类似外观；锈壁虱候选需同时观察果面黄褐色粉状物、受害分布及可见虫体，不能以果皮变色单独确诊。","growthStages":["幼果期","果实膨大期","成熟期"],"affectedParts":["果实","果皮","叶片"],"sourceVersion":"2021-11-15绿色防控方案；2025-08-28病虫情报；2026-11-14整理；2008-10-30柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["锈蜘蛛","柑橘锈壁虱","柑橘锈蜘蛛"],"identification":"主要危害叶片和果实。受害果面可出现灰尘般黄褐色粉状物，后果皮颜色和质地发生变化、表面粗糙；叶片受害可失绿。田间虫体微小，需结合放大观察和果面症状判断。","symptomKeywords":["锈壁虱","锈蜘蛛","灰尘状黄褐色粉状物","黄褐色粉状物","果皮褐化","果皮粗糙","叶片失绿"]}' AS JSON);
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9b38eaa6-9089-556b-a550-2c89e485ef37',1,'PUBLISHED','{"cropName":"番石榴","cropAliases":["芭乐","拔子","番桃"],"diseaseName":"炭疽病","diseaseAliases":["番石榴炭疽病"],"symptomKeywords":["红褐色斑点","黑褐色斑块","暗色霉状物","烂果","新梢焦枯","小黑点"],"affectedParts":["新梢","叶片","枝条","果实"],"growthStages":["新梢期","幼果期","成熟期"],"identification":"新梢和叶片可由褐变逐步焦枯，叶片病斑多为圆形或半圆形褐斑，中部变淡并可见小黑点；果实近成熟时从顶部出现红褐色斑点，逐渐扩大为黑褐色不规则斑块并长暗色霉状物，最后腐烂。","differential":"本条为公开资料整理的候选识别依据，不是现场确诊；需补拍整株、受害部位正反面、病健交界或虫体，记录病程、天气和近期投入品，证据不足或病情加重时采样交农技人员复核。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"怀化市农业农村局","sourceVersion":"2017-01-03公开全文；2026-11-14整理","sourceRef":"《防治番石榴炭疽病要打持久战》；http://www.huaihua.gov.cn/nyncj/c108787/201701/52ea8d91b7ad4003bd77bfb3cc2cd384.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9b38eaa6-9089-556b-a550-2c89e485ef37' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番石榴' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9b38eaa6-9089-556b-a550-2c89e485ef37' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '59ab88c6-52f7-5874-af44-99ce52b5e77d',1,'PUBLISHED','{"cropName":"番石榴","cropAliases":["芭乐","拔子","番桃"],"diseaseName":"根结线虫病","diseaseAliases":["番石榴根结线虫","根瘤线虫"],"symptomKeywords":["根部结瘤","根瘤","新叶变小","叶片黄化","叶尖枯萎","植株矮化","落叶"],"affectedParts":["根系","叶片","新梢"],"growthStages":["苗期","生长期"],"identification":"根系可见结瘤；受害植株常表现生长势弱、矮化、黄化、落叶，新叶变小，叶尖枯萎并伴似缺肥症状，节间缩短，新芽可能停止生长。","differential":"根结、黄化和缺肥样症状需结合挖根观察及样品检测；不得把缺素、积水或根腐病直接判定为线虫病。涉及种苗、土壤或调运的疑似病例，交植保植检机构复核。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"台湾农业知识入口网 / 芭乐主题馆","sourceVersion":"2025-07-31；2026-11-14整理","sourceRef":"《線蟲病害-芭樂(番石榴)主題館》；https://kmweb.moa.gov.tw/subject/subject.php?id=11755","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='59ab88c6-52f7-5874-af44-99ce52b5e77d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番石榴' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='根结线虫病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='59ab88c6-52f7-5874-af44-99ce52b5e77d' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '618b01b6-d081-5bd2-b48a-3345bf9c306c',1,'PUBLISHED','{"cropName":"番石榴","cropAliases":["芭乐","拔子","番桃"],"diseaseName":"枝枯病","diseaseAliases":["番石榴枝枯病"],"symptomKeywords":["新梢褐变","枝条枯萎","单侧落叶","叶片黄化","顶端枯死"],"affectedParts":["一年生枝","新梢","叶片"],"growthStages":["修剪后","雨季","生长期"],"identification":"感染枝枯病时，成熟叶片可逐渐黄化并从同一方向脱落；新梢及附近未展开叶片可褐变、萎蔫或死亡，侧枝也可能褐变枯萎。","differential":"与立枯病区分时关注病程和范围：枝枯病多限于一年生枝条顶端及其附近，立枯病可导致整枝条叶片黄化枯萎；仅有黄叶不能确诊。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"台湾农业知识入口网","sourceVersion":"2025-01-15；2026-11-14整理","sourceRef":"《番石榴植株病害發生及預防（三）》；https://kmweb.moa.gov.tw/theme_data.php?theme=news&sub_theme=variety&id=54864","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='618b01b6-d081-5bd2-b48a-3345bf9c306c' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番石榴' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='枝枯病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='618b01b6-d081-5bd2-b48a-3345bf9c306c' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '8d049109-a5bb-5ee0-8c69-cbb514f4f559',1,'PUBLISHED','{"cropName":"番石榴","cropAliases":["芭乐","拔子","番桃"],"diseaseName":"果实蝇","diseaseAliases":["番石榴果实蝇","桔小实蝇","东方果实蝇"],"symptomKeywords":["虫果","落果","果肉腐烂","蛆虫","果实蛀孔","果实腥臭"],"affectedParts":["果实","落果"],"growthStages":["幼果期","成熟期"],"identification":"雌虫刺入果皮产卵，幼虫在果内取食，受害果出现蛀孔、果肉腐烂并可含虫体，严重时提前落果；虫果和落果是田间监测重点。","differential":"果实软腐、机械伤或其他蛀果害虫均可能造成相似外观，需剖果或采虫鉴定；果实蝇为害番石榴、青枣等多种果蔬，不能据作物 单独 确定种类。","measures":"及时捡拾并密闭处理虫果、落果，幼果期套袋，结合诱捕器或诱虫板监测成虫，清理果园和越冬场所；具体统防统治按属地植保方案执行，不提供药剂处方。","source":"元江县人民政府信息公开","sourceVersion":"2014-05-27；2026-11-14整理","sourceRef":"《曼来镇果实蝇统防统治实施方案》；https://www.yjx.gov.cn/yjxzfxxgk/gzhgfxwj10653/20140527/540295.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='8d049109-a5bb-5ee0-8c69-cbb514f4f559' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='番石榴' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='果实蝇'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='8d049109-a5bb-5ee0-8c69-cbb514f4f559' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '9d906b3c-c207-5fe3-8f0c-890a992943e6',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"叶斑病","diseaseAliases":["香蕉叶斑病","黑条叶斑病"],"symptomKeywords":["叶片斑点","红色条斑","黑色病斑","叶片早衰","叶片枯黄"],"affectedParts":["叶片"],"growthStages":["苗期","生长期","雨季"],"identification":"叶斑类病害主要在叶片发生，初期可见红褐色或水浸状小斑、条斑，后扩大并转为褐黑色病斑，病叶逐渐早衰，雨水偏多时发生风险增加。","differential":"香蕉叶斑病包含多个病原和症状类型，需结合病斑形态、叶位、品种和样品检测区分黑条叶斑等具体病种；不凭黑斑单独确诊。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"农业农村部农垦局","sourceVersion":"2025-03-06全国香蕉重大病虫害发生趋势预报；2026-11-14整理","sourceRef":"https://nkj.moa.gov.cn/rzny/202503/t20250306_6471119.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='9d906b3c-c207-5fe3-8f0c-890a992943e6' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='叶斑病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='9d906b3c-c207-5fe3-8f0c-890a992943e6' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '2f38af3f-17ea-54ec-914b-96d9545b4a03',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"黑星病","diseaseAliases":["香蕉黑星病"],"symptomKeywords":["黑褐色突起小点","黑色斑点","果皮粗糙","水浸状边缘","果面黑斑"],"affectedParts":["叶片","果实"],"growthStages":["抽穗后","花果期","雨季"],"identification":"叶片或果实可出现圆形黑褐色至黑色突起小点，周围可有水浸状区域；抽穗后果面斑点由红褐或棕色逐渐转黑，果皮变粗糙，湿润多雨时风险上升。","differential":"需与叶斑病、机械伤、药害和果面污斑比较，检查斑点是否突起及其在叶片、果实上的分布；花果期发现疑似应交农技人员复核。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"农业农村部农垦局；农业知识入口网","sourceVersion":"2025-03-06；1998-01资料；2026-11-14整理","sourceRef":"趋势预报：https://nkj.moa.gov.cn/rzny/202503/t20250306_6471119.htm；黑星病识别：https://kmweb.moa.gov.tw/techcd/%E4%BD%9C%E7%89%A9%E7%97%85%E8%9F%B2%E5%AE%B3%E8%88%87%E8%82%A5%E5%9F%B9%E7%AE%A1%E7%90%86%E6%8A%80%E8%A1%93%E8%B3%87%E6%96%99/%E6%9E%9C%E6%A8%B9/%E5%B8%B8%E7%B6%A0%E6%9E%9C%E6%A8%B9/%E9%A6%99%E8%95%89/%E7%97%85%E5%AE%B3/%E9%A6%99%E8%95%89-%E9%BB%91%E6%98%9F%E7%97%85.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='2f38af3f-17ea-54ec-914b-96d9545b4a03' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='黑星病'));
