INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c15bae0b-2c84-5f1b-af98-29389d9a4510',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"枯萎病","diseaseAliases":["香蕉枯萎病","巴拿马病"],"symptomKeywords":["叶片黄化","叶片枯萎","侧折","病茎红褐色","整株死亡"],"affectedParts":["叶片","假茎","根系"],"growthStages":["生长期"],"identification":"感病植株可由叶片自下向上黄化、枯萎和侧折，部分病茎呈红色至红褐色，后期可能整株死亡；感病品种和砂壤土蕉园需重点监测。","differential":"黄化、萎蔫也可能由积水、缺素、根腐或其他维管束病害引起，需结合假茎切面、根系和实验室样品复核；疑似集中发生时暂停调运并联系属地植保植检机构。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"农业农村部农垦局","sourceVersion":"2025-03-06全国香蕉重大病虫害发生趋势预报；2026-11-14整理","sourceRef":"https://nkj.moa.gov.cn/rzny/202503/t20250306_6471119.htm","articleId":"","quarantine":true}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='c15bae0b-2c84-5f1b-af98-29389d9a4510' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='枯萎病'));
