INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'ec0d5f3d-15a1-5f48-8012-d2e659b9e267',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"细菌性软腐病","diseaseAliases":["香蕉软腐病"],"symptomKeywords":["水渍状病斑","软腐","组织腐烂","病茎变软","异味"],"affectedParts":["假茎","叶鞘","根茎"],"growthStages":["生长期","雨季"],"identification":"假茎、叶鞘或根茎部位可出现水渍状病变并逐步软腐，组织松软，湿度较高时腐烂扩展较快；带菌种苗、残体、土壤、雨水和农事操作都可能参与传播。","differential":"软腐也可能由真菌、机械伤或积水造成，需结合病部气味、组织和实验室检测区分；不得仅凭软腐外观确定细菌种类。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"广西壮族自治区农业农村厅","sourceVersion":"2025香蕉病虫害技术资料摘要；2026-11-14整理","sourceRef":"广西农业农村厅公开香蕉病虫害技术资料；https://nynct.gxzf.gov.cn/xwdt/gxlb/gg/P020250421584004668708.docx","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='ec0d5f3d-15a1-5f48-8012-d2e659b9e267' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='细菌性软腐病'));
