INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'b4636716-b1e9-528f-99fe-2f4df06b3edb',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"蓟马","diseaseAliases":["香蕉花蓟马","香蕉蓟马"],"symptomKeywords":["果皮褐斑","果皮锈斑","花器受害","幼果斑痕","细小细长虫体"],"affectedParts":["花","幼果","果实"],"growthStages":["花期","花果期"],"identification":"蓟马在花器和幼果期危害较明显，受害处可出现褐色或锈色斑痕，影响果面商品性；花果期应重点检查花器、果指和果穗。","differential":"果面擦伤、黑星病和药害也会产生褐斑或锈斑，需拍摄虫体、花器及受害部位近景；不因果皮斑痕直接判定蓟马。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"农业农村部农垦局；海南省市场监督管理局","sourceVersion":"2025-03-06；2023-07生产规范；2026-11-14整理","sourceRef":"趋势预报：https://nkj.moa.gov.cn/rzny/202503/t20250306_6471119.htm；生产规范：https://amr.hainan.gov.cn/zw/gsgg/qtgsgg/202307/P020230703309709443119.pdf","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='b4636716-b1e9-528f-99fe-2f4df06b3edb' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马'));
