INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '86086b7e-ca18-5348-a7e4-10feba732c73',1,'PUBLISHED','{"cropName":"香蕉","cropAliases":["香牙蕉","粉蕉","贡蕉"],"diseaseName":"红蜘蛛","diseaseAliases":["香蕉螨类","香蕉叶螨"],"symptomKeywords":["叶片失绿","细小斑点","叶背螨体","结网","叶片黄化"],"affectedParts":["叶片","叶背"],"growthStages":["旱季","高温期"],"identification":"红蜘蛛等螨类刺吸叶片，叶面可出现密集失绿小斑，严重时黄化，叶背可观察活动螨体或细丝；旱季和高温干燥条件下需加强巡查。","differential":"螨类、蓟马、缺素和药害均可造成失绿斑点，颜色不能单独确定螨种；需放大拍摄叶背虫体并由专业人员鉴定。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"农业农村部农垦局","sourceVersion":"2025-03-06全国香蕉重大病虫害发生趋势预报；2026-11-14整理","sourceRef":"https://nkj.moa.gov.cn/rzny/202503/t20250306_6471119.htm","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='86086b7e-ca18-5348-a7e4-10feba732c73' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='香蕉' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='红蜘蛛'));
