INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '250344ff-5052-54be-8ccf-e8edd1913b3d',1,'PUBLISHED','{"cropName":"青枣","cropAliases":["台湾青枣","台湾大青枣","台湾甜枣"],"diseaseName":"白粉病","diseaseAliases":["青枣白粉病"],"symptomKeywords":["白粉","果面白粉","果皮开裂","麻果","幼果脱落"],"affectedParts":["新梢","叶片","花穗","果实"],"growthStages":["幼果期","果实膨大期"],"identification":"白粉病可危害新梢、叶片、花穗和果实，幼果受害易脱落，大果果皮布满白粉，后期可能开裂并形成麻果，影响商品外观。","differential":"果面灰尘、药液残留和其他霉层可相似，需观察粉层是否持续扩展及受害部位；幼果脱落还可能与授粉、水分或营养因素有关。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"三明市农业农村局；湖南省林业局","sourceVersion":"2026-08-10；2023-06-08转载资料；2026-11-14整理","sourceRef":"https://smsnyj.sm.gov.cn/nyfw/nyjs/zzy/202608/t20260810_2268780.htm；https://lyj.hunan.gov.cn/lyj/tslm_71206/lysc/scxx/201512/t20151227_2694994.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='250344ff-5052-54be-8ccf-e8edd1913b3d' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='青枣' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='白粉病'));
