INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e461a6f6-3721-5f1e-ada0-0f1287ff60cf',1,'PUBLISHED','{"cropName":"青枣","cropAliases":["台湾青枣","台湾大青枣","台湾甜枣"],"diseaseName":"炭疽病","diseaseAliases":["青枣炭疽病"],"symptomKeywords":["淡褐色凹陷斑","粉红色霉层","朱红色小点","小黑点","果实腐烂"],"affectedParts":["果实","叶片","枝梢"],"growthStages":["幼果期","膨果期","成熟期"],"identification":"果实初期出现淡褐色稍凹陷病斑，保湿后病斑可长近粉红色霉层，并混有针头状朱红色或黑色小点，病果后期腐烂。","differential":"需与白粉病、疫病及机械伤比较，重点观察凹陷斑、霉层颜色和小点；仅有果面褐斑不能确诊。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"青枣主要病虫害公开技术资料","sourceVersion":"2021-12-06；2026-11-14整理","sourceRef":"http://shuju.aweb.com.cn/technology/20121013/228642.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='e461a6f6-3721-5f1e-ada0-0f1287ff60cf' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='青枣' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
