INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'e9381571-4e73-51d3-bf83-5a6882119f80',1,'PUBLISHED','{"cropName":"青枣","cropAliases":["台湾青枣","台湾大青枣","台湾甜枣"],"diseaseName":"疫病","diseaseAliases":["青枣疫病"],"symptomKeywords":["褐色水渍状","白色霉层","果实腐烂","落果"],"affectedParts":["果实","枝梢"],"growthStages":["雨季","果实膨大期"],"identification":"果实受害时外表形成褐色水渍状病斑，后期病部可出现白色霉层并导致果实腐烂、落果；高湿和积水条件下应加强排查。","differential":"水渍状腐烂也可能由炭疽病、灰霉或机械伤继发感染造成，需观察霉层和病部扩展并采样复核。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"青枣主要病虫害公开技术资料","sourceVersion":"2021-12-06；2026-11-14整理","sourceRef":"http://shuju.aweb.com.cn/technology/20121013/228642.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='e9381571-4e73-51d3-bf83-5a6882119f80' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='青枣' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='疫病'));
