INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '285b9c2e-2c46-5cce-8bcb-b3c1f9b06f33',1,'PUBLISHED','{"cropName":"青枣","cropAliases":["台湾青枣","台湾大青枣","台湾甜枣"],"diseaseName":"轮斑病","diseaseAliases":["青枣轮斑病"],"symptomKeywords":["叶片褐斑","轮纹斑","叶片黄化","早落叶"],"affectedParts":["叶片"],"growthStages":["生长期","高温高湿期"],"identification":"叶片初期可出现褐色小斑，病斑扩大后形成轮纹或同心轮状结构，严重时叶片黄化并早落。","differential":"需与锈病、炭疽病、药害和缺素斑比较，保留病斑完整轮纹及叶片正反面照片；不凭叶片褐斑直接确诊。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"青枣主要病虫害公开技术资料","sourceVersion":"2021-12-06；2026-11-14整理","sourceRef":"http://shuju.aweb.com.cn/technology/20121013/228642.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='285b9c2e-2c46-5cce-8bcb-b3c1f9b06f33' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='青枣' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='轮斑病'));
