INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c225edee-c3e6-547c-8a22-57c8851a5c42',1,'PUBLISHED','{"cropName":"青枣","cropAliases":["台湾青枣","台湾大青枣","台湾甜枣"],"diseaseName":"果实蝇","diseaseAliases":["青枣果实蝇","桔小果实蝇"],"symptomKeywords":["虫果","落果","蛆虫","果肉腐烂","果实蛀孔"],"affectedParts":["果实","落果"],"growthStages":["幼果期","成熟期"],"identification":"果实蝇可危害青枣，雌虫刺入果皮产卵，幼虫蛀食果肉，造成虫果、腐烂和落果；应结合落果剖查、诱捕和套袋进行监测。","differential":"桔小果实蝇、番石榴果实蝇等可共同危害多种果蔬，果实腐烂不代表具体种类，需采虫鉴定。","measures":"及时清理并密闭处理虫果、落果，幼果期套袋，结合黄色诱板或诱捕器监测成虫；按属地植保要求开展区域联防，不提供药剂处方。","source":"元江县人民政府信息公开；湖南省林业局","sourceVersion":"2014-05-27；2023-06-08转载资料；2026-11-14整理","sourceRef":"果实蝇方案：https://www.yjx.gov.cn/yjxzfxxgk/gzhgfxwj10653/20140527/540295.html；青枣资料：https://lyj.hunan.gov.cn/lyj/tslm_71206/lysc/scxx/201512/t20151227_2694994.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='c225edee-c3e6-547c-8a22-57c8851a5c42' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='青枣' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='果实蝇'));
