INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '56036e49-7e5f-5473-a50e-89232555bea5',1,'PUBLISHED','{"cropName":"杨桃","cropAliases":["五敛子","阳桃"],"diseaseName":"鸟羽蛾","diseaseAliases":["杨桃鸟羽蛾","红线虫","白蚊"],"symptomKeywords":["花内蛀食","花穗枯死","落花","幼果蛀食","叶片孔洞"],"affectedParts":["花","花穗","幼果","叶片"],"growthStages":["盛花期","幼果期","6-8月"],"identification":"幼虫钻入花内蛀食小花，可造成花穗枯死和大量落花；也可危害幼果并使其脱落，叶片受害时出现缺刻或孔洞。","differential":"需观察幼虫、花内蛀食痕和发生期，与小卷叶蛾、其他食花幼虫或机械损伤区分；不凭落花直接判定鸟羽蛾。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"湖南省林业局","sourceVersion":"2013-06-03；2026-11-14整理","sourceRef":"《杨桃鸟羽蛾防治》；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2590148.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='56036e49-7e5f-5473-a50e-89232555bea5' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='杨桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='鸟羽蛾'));
