INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '2237f6ea-a867-57a3-9c7a-d6ef5a946b05',1,'PUBLISHED','{"cropName":"杨桃","cropAliases":["五敛子","阳桃"],"diseaseName":"果实蝇","diseaseAliases":["杨桃果实蝇","桔小实蝇"],"symptomKeywords":["虫果","落果","蛆虫","果肉腐烂","果实蛀孔"],"affectedParts":["果实","落果"],"growthStages":["幼果期","成熟期"],"identification":"桔小实蝇等果实蝇可在杨桃果实内产卵，幼虫取食造成虫果、果肉腐烂和落果；成熟期应加强落果检查和诱捕监测。","differential":"多种实蝇可共同危害杨桃、番石榴和其他果树，需通过虫体、果内幼虫或专业检测区分，不能凭蛆果直接确定种名。","measures":"及时清理虫果和落果并进行密闭、深埋或热处理，幼果期套袋，结合黄板或性诱装置监测成虫；具体区域防控按属地植保方案执行。","source":"广州市农业农村局；元江县人民政府信息公开","sourceVersion":"2022-08-15公开病虫情报；2014-05-27综合方案；2026-11-14整理","sourceRef":"https://nyncj.gz.gov.cn/attachment/7/7147/7147076/8508403.pdf；https://www.yjx.gov.cn/yjxzfxxgk/gzhgfxwj10653/20140527/540295.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='2237f6ea-a867-57a3-9c7a-d6ef5a946b05' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='杨桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='果实蝇'));
