INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '6c78fac9-3296-5831-a6f0-bdce387928e2',1,'PUBLISHED','{"cropName":"杨桃","cropAliases":["五敛子","阳桃"],"diseaseName":"赤斑病","diseaseAliases":["杨桃赤斑病"],"symptomKeywords":["红褐色斑点","赤褐斑","叶片斑点","果面病斑"],"affectedParts":["叶片","枝条","果实"],"growthStages":["生长期","果实膨大期"],"identification":"杨桃常见病害之一，病部可出现红褐色或赤褐色斑点，需结合叶片、枝条和果面受害部位观察。","differential":"资料对赤斑病的症状描述较概括，需与炭疽病、细菌性斑点病、擦伤和药害区分，发现疑似应补拍病健交界并采样。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"湖南省林业局","sourceVersion":"2004-07-14；2026-11-14整理","sourceRef":"《四季红杨桃栽培管理》；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2617546.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='6c78fac9-3296-5831-a6f0-bdce387928e2' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='杨桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='赤斑病'));
