INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '1db57c90-b568-5f02-9af5-1220b3bcdd4e',1,'PUBLISHED','{"cropName":"杨桃","cropAliases":["五敛子","阳桃"],"diseaseName":"炭疽病","diseaseAliases":["杨桃炭疽病"],"symptomKeywords":["褐色斑点","黑褐色病斑","果实腐烂","暗色霉层"],"affectedParts":["叶片","枝条","果实"],"growthStages":["幼果期","成熟期","高温高湿期"],"identification":"杨桃炭疽病可危害果实等部位，病部可出现褐色至黑褐色斑点并逐步腐烂；高温高湿和果面损伤会增加发生风险。","differential":"需与赤斑病、细菌性斑点病和果实蝇蛀果区分，重点观察病斑边界、霉层、蛀孔和虫体；疑似病例应采样复核。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"湖南省林业局","sourceVersion":"2004-07-14；2026-11-14整理","sourceRef":"《四季红杨桃栽培管理》；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2617546.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='1db57c90-b568-5f02-9af5-1220b3bcdd4e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='杨桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
