INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'bbdcc887-e7a5-5f54-9c42-f08620d4a65e',1,'PUBLISHED','{"cropName":"杨桃","cropAliases":["五敛子","阳桃"],"diseaseName":"胶介壳虫","diseaseAliases":["杨桃胶介壳虫","介壳虫"],"symptomKeywords":["介壳","枝条虫体","叶片黄化","蜜露","煤污"],"affectedParts":["枝条","叶片","果实"],"growthStages":["新梢期","果实膨大期"],"identification":"胶介壳虫等介壳虫可附着枝条、叶片或果面刺吸危害，可能伴随蜜露和煤污，严重时叶片失绿、枝梢衰弱。","differential":"介壳、蚜虫、粉虱及煤污均可能造成相似外观，需拍清固定虫体、蜡壳或蜜露来源；不能以煤污单独确定介壳虫种类。","measures":"加强果园清洁、合理修剪和通风排水，及时清理病虫枝、落果和残体并按属地要求无害化处理；结合监测、套袋、诱捕或生物防控等措施综合管理。本条不提供药剂、剂量、混配、安全间隔或固定防治阈值；用药须核对当前有效的作物、防治对象登记和标签，由农技人员复核。","source":"湖南省林业局","sourceVersion":"2004-07-14；2026-11-14整理","sourceRef":"《四季红杨桃栽培管理》；http://lyj.hunan.gov.cn/tslm_71206/lykp/syjs/201512/t20151227_2617546.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='bbdcc887-e7a5-5f54-9c42-f08620d4a65e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='杨桃' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='胶介壳虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='bbdcc887-e7a5-5f54-9c42-f08620d4a65e' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '25e8af2c-e183-5567-a306-9259c872ae8c',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"溃疡病","diseaseAliases":["火龙果溃疡病"],"symptomKeywords":["浅黄色凹陷病斑","红褐色针状点","木栓化突起","白色木栓化病斑","圆形穿孔","溃疡病"],"affectedParts":["肉质茎","果实"],"growthStages":["生长期","果实膨大期"],"identification":"肉质茎和果实可见圆形浅黄色凹陷斑，中央出现红褐色针状点，逐渐成褐色突起；干燥时灰白木栓化，潮湿时茎腐烂、干后可穿孔。高温高湿有利发生。公开研究将部分文献中的褐腐病用于相同病原相关病害，但本条不将泛称褐腐或疮痂病自动合并为别名。","differential":"须与炭疽、其他茎斑及日灼、冻害结痂区分；病原需实验室鉴定，不能凭果皮麻点确定。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"选健康繁殖材料，晴好天气修剪病枝并清理残体，平衡施肥；病重园可由农技人员评估避雨栽培。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='25e8af2c-e183-5567-a306-9259c872ae8c' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='溃疡病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='25e8af2c-e183-5567-a306-9259c872ae8c' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a6be3152-ee90-59e6-b8e8-4d792fed63f1',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"炭疽病","diseaseAliases":["火龙果炭疽病"],"symptomKeywords":["紫褐色凹陷小斑","散生凹陷斑","圆形或棱形病斑","肉质部干枯","病斑黑色小点","炭疽病"],"affectedParts":["肉质茎","果实"],"growthStages":["生长期","结果期"],"identification":"历史粤西调查描述茎节初现紫褐色散生凹陷小斑，扩大为圆形或棱形，可连片使肉质部干枯，病斑散生黑色小点；广西农科院资料确认该病在火龙果上发生。这里只保存症候，不将历史病原命名当作现场鉴定。","differential":"与溃疡、茎枯、机械伤及日灼比较；凹陷或黑点不能单独确诊，果实症状需另拍清晰近景。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"减少病残体和雨水飞溅，工具清洁消毒，避免带病繁殖材料。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"农博网（历史调查转载，仅提取症状）；广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2012-10-12历史调查转载；2023-04-13；2025-06-06综合管理；2026-11-14整理","sourceRef":"《粤西地区火龙果病害调查初报及防治措施》：http://shuju.aweb.com.cn/technology/20121013/224226.html；综合管理：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml；病害存在依据：http://www.gxaas.net/front/detail/143/3739/94219","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='a6be3152-ee90-59e6-b8e8-4d792fed63f1' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='炭疽病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a6be3152-ee90-59e6-b8e8-4d792fed63f1' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '6b82614e-fb71-5d36-bc5f-270e8c6f7888',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"细菌性软腐病","diseaseAliases":["火龙果软腐病","软腐病","火龙果细菌性软腐病"],"symptomKeywords":["水浸状半透明","黏滑软腐","腥臭","茎节腐烂","仅剩木质部","细菌性软腐病"],"affectedParts":["肉质茎","嫩茎"],"growthStages":["生长期","苗期"],"identification":"历史调查描述病部初呈水浸状半透明，继而黏滑软腐并有腥臭，可蔓延整节，最后仅剩中心木质部；多与嫩节伤口、虫咬及潮湿有关。广西农科院指出有不同细菌属相关报告，不能从照片确定细菌种。","differential":"与湿腐、其他茎腐、冻害后继发腐烂及积水伤根区分；臭味与水浸不能作为病原确证，快速扩展时尽快专业采样。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"避免人为伤口和雨天操作，清洁工具，隔离带病繁殖材料，清除病残体并改善排水。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"农博网（历史调查转载，仅提取症状）；广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2012-10-12历史调查转载；2023-04-13；2025-06-06综合管理；2026-11-14整理","sourceRef":"《粤西地区火龙果病害调查初报及防治措施》：http://shuju.aweb.com.cn/technology/20121013/224226.html；综合管理：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml；病害存在依据：http://www.gxaas.net/front/detail/143/3739/94219","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='6b82614e-fb71-5d36-bc5f-270e8c6f7888' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='细菌性软腐病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='6b82614e-fb71-5d36-bc5f-270e8c6f7888' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'c0c81086-09a9-5fe6-a87f-a4a9d30e8b7e',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"根结线虫病","diseaseAliases":["火龙果根结线虫病","根结线虫"],"symptomKeywords":["侧根根结","主根根结","肉质茎脱水干瘪","根结","侧根腐烂"],"affectedParts":["根系","肉质茎"],"growthStages":["生长期"],"identification":"初期地上肉质茎轻度脱水，侧根开始出现根结；后期茎脱水干瘪发黄、甚至枯死，主根较大根结并伴侧根腐烂。需采根和根际土检测，不从地上萎蔫直接判断。","differential":"须排除干旱、积水烂根及其他根病；根瘤并非全部由根结线虫引起，线虫种群或种类由专业检测确认。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"选无根结健康苗，防止带病根土及农具跨园传播，按专业方案采样并清洁消毒农具。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='c0c81086-09a9-5fe6-a87f-a4a9d30e8b7e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='根结线虫病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='c0c81086-09a9-5fe6-a87f-a4a9d30e8b7e' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '12003c0b-e7e8-5e85-ba58-dc369f27661b',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"煤烟病","diseaseAliases":["火龙果煤烟病","煤污病"],"symptomKeywords":["黑色霉层","果实布满霉层","蜜露","煤烟","煤污"],"affectedParts":["肉质茎","花","果实"],"growthStages":["生长期","花期","结果期"],"identification":"肉质茎、花和果实表面可出现黑色霉层，常与蜜露或糖性分泌物有关，严重时覆盖果实。广西农科院资料指出植株分泌物也可提供生长基质。","differential":"黑色霉层不能直接证明有蚜虫或粉蚧；核查分泌物和虫体，与坏死斑、尘污、腐烂区分。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"检查蜜露来源并同步监测刺吸害虫，合理修剪、通风和平衡施肥；清洁操作避免增加长期高湿。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='12003c0b-e7e8-5e85-ba58-dc369f27661b' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='煤烟病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='12003c0b-e7e8-5e85-ba58-dc369f27661b' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'bdaddbdb-59d3-5848-aa66-f8556078e03b',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"湿腐病","diseaseAliases":["火龙果湿腐病"],"symptomKeywords":["花水浸状腐烂","残花处腐烂","幼果褐变腐烂","半边果","黑心果","湿腐病"],"affectedParts":["花","幼果","果实"],"growthStages":["花期","幼果期","采收期"],"identification":"高温高湿时花出现水浸状腐烂和落花；幼果可从衰败花瓣附近开始果皮果肉褐变，干燥后结痂，重者形成半边果或黑心果。雨天采收后可见快速水浸腐烂。","differential":"与细菌性软腐、炭疽、果实蝇为害和采后伤腐鉴别；本条不凭湿腐表现推定具体病原或等同细菌性软腐病。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"在农技指导下及时处理衰败花瓣与病花病果，保持通风、减少果面持续潮湿，尽量避免雨天采收和机械伤。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='bdaddbdb-59d3-5848-aa66-f8556078e03b' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='湿腐病'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='bdaddbdb-59d3-5848-aa66-f8556078e03b' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7757edc7-2a75-565e-9011-392d7de053cb',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"夜蛾类","diseaseAliases":["火龙果夜蛾类","斜纹夜蛾","甜菜夜蛾"],"symptomKeywords":["嫩茎缺刻","生长点被啃食","花蕾被啃食","幼虫取食果皮","夜蛾","斜纹夜蛾","甜菜夜蛾"],"affectedParts":["嫩茎","生长点","花蕾","幼果"],"growthStages":["新梢期","花蕾期","幼果期"],"identification":"斜纹夜蛾与甜菜夜蛾幼虫均可取食嫩茎形成缺刻，损伤生长点使嫩茎停长；取食花蕾可致落蕾，啃食幼果果皮形成花皮果。本条将重叠为害症状作为夜蛾类合并候选。","differential":"不能凭缺刻、花皮果区分斜纹夜蛾和甜菜夜蛾，也须与蜗牛及其他食叶幼虫区分；补拍幼虫头胸腹部、卵块或采虫鉴定。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"清理病虫残体与适度控草，监测卵块和低龄幼虫，保护天敌；物种确认后由专业人员选择相应性诱监测方案。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7757edc7-2a75-565e-9011-392d7de053cb' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='夜蛾类'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7757edc7-2a75-565e-9011-392d7de053cb' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '89238061-f8a7-536b-9f7e-02540dc6cc07',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"蓟马","diseaseAliases":["火龙果蓟马"],"symptomKeywords":["鳞片基部受害","鳞片锉吸伤","花皮果","蓟马","幼果鳞片受害"],"affectedParts":["嫩茎","花","幼果","鳞片"],"growthStages":["新梢期","花期","幼果期"],"identification":"蓟马可为害嫩茎、花和幼果，以花和幼果受害突出；锉吸幼果鳞片及鳞片基部，可出现花皮果。需观察小型活动虫体。","differential":"与擦伤、夜蛾啃食、螨害和其他花皮原因区分；不能凭鳞片伤确定西花蓟马等具体种，也不由此判定病毒感染。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"监测花内与幼果鳞片虫体，合理控草，黄蓝粘板用于监测和辅助诱控，保护天敌。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='89238061-f8a7-536b-9f7e-02540dc6cc07' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蓟马'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='89238061-f8a7-536b-9f7e-02540dc6cc07' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '7f1624f4-3ff1-574c-b976-7082189d5a93',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"橘小实蝇","diseaseAliases":["桔小实蝇","东方果实蝇","火龙果橘小实蝇"],"symptomKeywords":["果内蛆状幼虫","果肉被取食","虫果落果","橘小实蝇","桔小实蝇","果内幼虫"],"affectedParts":["果实"],"growthStages":["结果期","成熟期"],"identification":"成虫可在果实内产卵，孵化幼虫在果内取食形成虫果，严重时落果。需结合剖果虫体、成虫诱捕及专业鉴定。","differential":"与桃蛀螟等蛀果虫及单纯腐烂区分；果内有蛆不能直接确定为橘小实蝇，更不能混同柑橘大实蝇或其他实蝇。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"及时清理虫果、落果，按属地要求无害化处理，评估幼果防虫套袋并配合规范诱捕监测。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='7f1624f4-3ff1-574c-b976-7082189d5a93' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='橘小实蝇'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='7f1624f4-3ff1-574c-b976-7082189d5a93' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT '3ee4e629-bfc7-5cb2-b3f0-b9427afadec1',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"蚜虫","diseaseAliases":["火龙果蚜虫"],"symptomKeywords":["鳞片变黄萎缩","花畸形","蚜虫","花上虫群","幼果鳞片萎缩"],"affectedParts":["花","幼果","鳞片"],"growthStages":["花期","幼果期"],"identification":"蚜虫刺吸花和幼果，可致花与幼果鳞片变黄萎缩，重者花畸形。需拍清虫群，检查套袋幼果等隐蔽部位。","differential":"与蓟马、粉蚧、营养或授粉异常区分；蚜虫存在不代表感染病毒，也不由症状直接判虫种。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"监测花果及袋内虫情，合理控草和清理修剪残体，黄板用于监测辅助诱控，保护瓢虫等天敌。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='3ee4e629-bfc7-5cb2-b3f0-b9427afadec1' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蚜虫'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='3ee4e629-bfc7-5cb2-b3f0-b9427afadec1' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'a17ad094-fb1d-5ae4-906b-ee5713d6aad8',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"蜗牛","diseaseAliases":["火龙果蜗牛"],"symptomKeywords":["不规则取食孔洞","薄膜般爬痕","黏液爬痕","蜗牛","嫩茎停长"],"affectedParts":["肉质茎","花蕾","幼果","生长点"],"growthStages":["新梢期","花蕾期","幼果期"],"identification":"雨后或有露水的夜晚取食肉质茎、花蕾、幼果，留下不规则孔洞和薄膜般爬痕；取食生长点可使嫩茎停长。","differential":"与夜蛾、蛞蝓或其他咀嚼害物区分；爬痕不能直接确认蜗牛种类，需拍清动物及壳形。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"减少隐蔽孳生场所、改善排水，雨后巡查并由人工收集及属地认可的物理措施控制；不照搬历史石灰或自制浸液处方。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西农业科学院 / 广西南亚热带农业科学研究所；广西壮族自治区农业农村厅","sourceVersion":"2023-04-13识别；2025-06-06综合管理；2026-11-14整理","sourceRef":"《崇左市火龙果主要病虫害及其防治》：http://www.gxaas.net/front/detail/143/3739/94219；《火龙果病虫害绿色防控技术》：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='a17ad094-fb1d-5ae4-906b-ee5713d6aad8' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='蜗牛'));
INSERT IGNORE INTO agri_prod_pest_atlas_revision(id,revision,status,payload_json,recorded_at) SELECT id,revision,status,payload_json,updated_at FROM agri_prod_pest_atlas WHERE id='a17ad094-fb1d-5ae4-906b-ee5713d6aad8' AND revision=1 AND status='PUBLISHED';
INSERT IGNORE INTO agri_prod_pest_atlas(id,revision,status,payload_json,created_at,updated_at,published_at) SELECT 'ecf9d01f-8e88-57bb-9d17-8535dff3355e',1,'PUBLISHED','{"cropName":"火龙果","cropAliases":["红龙果","红肉火龙果","红心火龙果","白肉火龙果","白心火龙果"],"diseaseName":"堆蜡粉蚧","diseaseAliases":["火龙果堆蜡粉蚧"],"symptomKeywords":["厚白色蜡粉","四列蜡堆","紫黑色虫体","绵状蜡质卵囊","堆蜡粉蚧"],"affectedParts":["嫩梢","茎","果实"],"growthStages":["生长期","新梢期","结果期"],"identification":"广西2025年火龙果绿色防控资料将堆蜡粉蚧列为重点虫害；广州林业资料的形态鉴别为紫黑色椭圆虫体，背面白色蜡粉可呈四列蜡堆、体缘短蜡丝及绵状蜡质卵囊。形态资料并非火龙果田间确诊。","differential":"须与其他粉蚧、介壳虫、菌丝及药物残留区分；仅见白粉或煤污不能确定为堆蜡粉蚧，需虫体显微近照或送检，园林寄主药剂不能外推到火龙果。 本条仅作候选筛查，不能凭单一关键词确诊；补拍整株、受害部位近景，必要时采样送专业机构。","measures":"规范检查嫩梢及隐蔽部位，保护捕食性或寄生性天敌，合理修剪、清洁田园并持续记录虫情。 加强监测并记录品种、生育阶段、降雨湿度、症状时间和近期农事；合理修剪、通风排水，避免积水及长期喷灌，选用健康种苗，病虫残体依属地要求无害化处理。 不导入历史药剂、剂量、混配、安全间隔或固定防治阈值；需要用药由农技人员核对当前有效登记、作物、防治对象和标签。","source":"广西壮族自治区农业农村厅（火龙果适用）；广州市林业和园林局（虫体形态）","sourceVersion":"2025-06-06火龙果适用；2017-11-29虫体形态；2026-11-14整理","sourceRef":"火龙果适用及综合管理：http://nynct.gxzf.gov.cn/xwdt/gxlb/gg/t21175754.shtml；《园林植物常见病虫害——堆蜡粉蚧》虫体形态（不外推园林用药）：https://lyylj.gz.gov.cn/kpyd/zhzy/content/post_3032225.html","articleId":"","quarantine":false}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agri_prod_pest_atlas WHERE id='ecf9d01f-8e88-57bb-9d17-8535dff3355e' OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.cropName'))='火龙果' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.diseaseName'))='堆蜡粉蚧'));
