UPDATE agri_prod_pest_atlas SET payload_json='{"source":"安远县人民政府；农业农村部 / 全国农技推广服务中心；尤溪县农业农村局","cropName":"柑橘","measures":"减少雨露未干时的穿园操作，合理控梢、保持通风并监测潜叶蛾伤口；发现疑似及时联系属地植保植检机构，核查繁殖材料来源和调运要求。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","articleId":"","sourceRef":"《柑橘溃疡病的发生与防治》识别及农业管理段；https://www.ay.gov.cn/ayzf/c138678depunvpuhgqd/202606/0746640db686465c960186998119811c.shtml；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm；蜜柚/柚类适用依据：http://www.fjyx.gov.cn/ztzl/snxx/bcqb/202603/t20260316_2194808.htm","quarantine":false,"cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"溃疡病","differential":"与疮痂、机械伤和潜叶蛾伤口比较，双面隆起及火山口裂纹是重点；确证需专业检测。是否属属地补充检疫对象及调运要求由植检机构核定。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","growthStages":["新梢期","幼果期","果实膨大期"],"affectedParts":["叶片","枝梢","果实"],"sourceVersion":"2026-06-01；2025-02-28；2026-11-14公开资料整理；2026-03-16柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘溃疡病"],"identification":"叶背初生淡黄色油浸状小点，后叶正反面同时隆起，形成灰褐色木栓化病斑，中心火山口状凹陷开裂、周围黄色晕环；枝梢斑更突起，果实斑更大且木栓化明显。","symptomKeywords":["火山口状开裂","正反两面隆起","木栓化病斑","油浸状小点","黄色晕环"]}',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id='9627ea6f-d3a2-5d34-928f-ad1dc9312869' AND revision=1 AND status='PUBLISHED' AND payload_json=CAST('{"source":"安远县人民政府；农业农村部 / 全国农技推广服务中心","cropName":"柑橘","measures":"减少雨露未干时的穿园操作，合理控梢、保持通风并监测潜叶蛾伤口；发现疑似及时联系属地植保植检机构，核查繁殖材料来源和调运要求。 不导入历史药剂、剂量、混配或安全间隔；需要用药须由农技人员核对当前有效登记、作物、防治对象及属地要求。","articleId":"","sourceRef":"《柑橘溃疡病的发生与防治》识别及农业管理段；https://www.ay.gov.cn/ayzf/c138678depunvpuhgqd/202606/0746640db686465c960186998119811c.shtml；综合管理：https://www.moa.gov.cn/xw/zxfb/202502/t20250228_6470757.htm","quarantine":false,"cropAliases":["柑桔","橘树","橘子","桔子","脐橙","甜橙","蜜柑"],"diseaseName":"溃疡病","differential":"与疮痂、机械伤和潜叶蛾伤口比较，双面隆起及火山口裂纹是重点；确证需专业检测。是否属属地补充检疫对象及调运要求由植检机构核定。 本条仅作候选识别，不能凭单个关键词确诊；补拍整株、病部正反面及近景，记录症状出现时间、品种、物候和近期投入品。","growthStages":["新梢期","幼果期","果实膨大期"],"affectedParts":["叶片","枝梢","果实"],"sourceVersion":"2026-06-01；2025-02-28；2026-11-14公开资料整理","diseaseAliases":["柑橘溃疡病"],"identification":"叶背初生淡黄色油浸状小点，后叶正反面同时隆起，形成灰褐色木栓化病斑，中心火山口状凹陷开裂、周围黄色晕环；枝梢斑更突起，果实斑更大且木栓化明显。","symptomKeywords":["火山口状开裂","正反两面隆起","木栓化病斑","油浸状小点","黄色晕环"]}' AS JSON);
UPDATE agri_prod_pest_atlas SET payload_json='{"source":"农业农村部农产品质量安全监管司；平阳县农业局；云浮市农业农村局","cropName":"柑橘","measures":"加强冬春清园，剪除病虫枯枝、摘除病果并按属地要求集中处理；合理修剪改善通风透光，均衡水肥、避免偏施氮肥，及时采收并减少采后损伤。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","articleId":"","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；识别与管理：https://www.zjpy.gov.cn/art/2014/5/8/art_1257318_4714255.html；蜜柚/柚类适用依据：https://www.yunfu.gov.cn/nyncj/zdht/syjs/content/post_377939.html","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"炭疽病","differential":"需与砂皮病、疮痂病、灰霉病、日灼、机械伤及药害区分。红色黏质小点、同心轮纹和受害部位组合可作为候选依据，但单一叶斑、落果或腐烂不能确诊；应补拍病健交界、枝梢和果面，并结合病程与近期管理记录采样复核。","growthStages":["春梢期","幼果期","果实膨大期","采收期","贮藏期"],"affectedParts":["叶片","枝梢","花","果实","果梗","苗木"],"sourceVersion":"2022-12-28公开指导意见；2014-05-08病害技术资料；2026-11-14整理；2019-04-23柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["柑橘炭疽病"],"identification":"可危害柑橘地上部多个部位。叶片病斑多在叶缘或叶尖，呈浅灰褐色或不规则形，病健交界清楚，病斑上可见同心轮纹排列的黑色小点；高温多湿或树势弱时可出现叶尖向下扩展的烫伤状急性症状。枝梢病斑可呈梭形并伴黑色小粒点，果实可出现凹陷斑、泪痕状病斑或软腐。","symptomKeywords":["炭疽","同心轮纹","黑色小点","肉红色黏质小点","烫伤状","泪痕型","软腐","落叶","落果"]}',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a101' AND revision=1 AND status='PUBLISHED' AND payload_json=CAST('{"source":"农业农村部农产品质量安全监管司；平阳县农业局","cropName":"柑橘","measures":"加强冬春清园，剪除病虫枯枝、摘除病果并按属地要求集中处理；合理修剪改善通风透光，均衡水肥、避免偏施氮肥，及时采收并减少采后损伤。具体用药须由农技人员依据当前有效登记、适用对象和标签核对，本条不提供药剂、剂量、混配或安全间隔处方。","articleId":"","sourceRef":"农业农村部指导意见：https://jgs.moa.gov.cn/fxpg/202212/t20221228_6417846.htm；识别与管理：https://www.zjpy.gov.cn/art/2014/5/8/art_1257318_4714255.html","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"炭疽病","differential":"需与砂皮病、疮痂病、灰霉病、日灼、机械伤及药害区分。红色黏质小点、同心轮纹和受害部位组合可作为候选依据，但单一叶斑、落果或腐烂不能确诊；应补拍病健交界、枝梢和果面，并结合病程与近期管理记录采样复核。","growthStages":["春梢期","幼果期","果实膨大期","采收期","贮藏期"],"affectedParts":["叶片","枝梢","花","果实","果梗","苗木"],"sourceVersion":"2022-12-28公开指导意见；2014-05-08病害技术资料；2026-11-14整理","diseaseAliases":["柑橘炭疽病"],"identification":"可危害柑橘地上部多个部位。叶片病斑多在叶缘或叶尖，呈浅灰褐色或不规则形，病健交界清楚，病斑上可见同心轮纹排列的黑色小点；高温多湿或树势弱时可出现叶尖向下扩展的烫伤状急性症状。枝梢病斑可呈梭形并伴黑色小粒点，果实可出现凹陷斑、泪痕状病斑或软腐。","symptomKeywords":["炭疽","同心轮纹","黑色小点","肉红色黏质小点","烫伤状","泪痕型","软腐","落叶","落果"]}' AS JSON);
UPDATE agri_prod_pest_atlas SET payload_json='{"source":"怀化市鹤城区农业农村局；清远市清新区农业农村局；农业农村部门户柑橘专栏","cropName":"柑橘","measures":"加强幼果至膨果期果面和叶片巡查，记录虫情空间分布，合理修剪、清园并保护天敌；防治阈值和处置时机采用属地植保方案，不能跨区域直接套用。具体用药须由农技人员依据当前有效登记和标签核对。","articleId":"","sourceRef":"绿色防控方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml；病虫情报：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2053052.html；蜜柚/柚类适用依据：https://www.moa.gov.cn/ztzl/gjcxzl/jkxf/200810/t20081030_1163931.htm","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬","蜜柚","琯溪蜜柚","红肉蜜柚","三红蜜柚"],"diseaseName":"锈壁虱","differential":"果面灰尘、药液残留、砂皮病和日灼均可能造成类似外观；锈壁虱候选需同时观察果面黄褐色粉状物、受害分布及可见虫体，不能以果皮变色单独确诊。","growthStages":["幼果期","果实膨大期","成熟期"],"affectedParts":["果实","果皮","叶片"],"sourceVersion":"2021-11-15绿色防控方案；2025-08-28病虫情报；2026-11-14整理；2008-10-30柚类适用依据；2026-11-14补充蜜柚别名","diseaseAliases":["锈蜘蛛","柑橘锈壁虱","柑橘锈蜘蛛"],"identification":"主要危害叶片和果实。受害果面可出现灰尘般黄褐色粉状物，后果皮颜色和质地发生变化、表面粗糙；叶片受害可失绿。田间虫体微小，需结合放大观察和果面症状判断。","symptomKeywords":["锈壁虱","锈蜘蛛","灰尘状黄褐色粉状物","黄褐色粉状物","果皮褐化","果皮粗糙","叶片失绿"]}',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id='c9e0a1f4-4c0b-5f9b-9a4a-4f77d2e8a105' AND revision=1 AND status='PUBLISHED' AND payload_json=CAST('{"source":"怀化市鹤城区农业农村局；清远市清新区农业农村局","cropName":"柑橘","measures":"加强幼果至膨果期果面和叶片巡查，记录虫情空间分布，合理修剪、清园并保护天敌；防治阈值和处置时机采用属地植保方案，不能跨区域直接套用。具体用药须由农技人员依据当前有效登记和标签核对。","articleId":"","sourceRef":"绿色防控方案：https://www.hechengqu.gov.cn/hechengqu/c115686/202111/465cc0f7fbe4436ba01b0ad5a2bce187.shtml；病虫情报：https://www.qingxin.gov.cn/bmxz/bm/qxqnyncj/qt/bmdt/content/post_2053052.html","quarantine":false,"cropAliases":["柑桔","橘子","橙子","柚子","柠檬"],"diseaseName":"锈壁虱","differential":"果面灰尘、药液残留、砂皮病和日灼均可能造成类似外观；锈壁虱候选需同时观察果面黄褐色粉状物、受害分布及可见虫体，不能以果皮变色单独确诊。","growthStages":["幼果期","果实膨大期","成熟期"],"affectedParts":["果实","果皮","叶片"],"sourceVersion":"2021-11-15绿色防控方案；2025-08-28病虫情报；2026-11-14整理","diseaseAliases":["锈蜘蛛","柑橘锈壁虱","柑橘锈蜘蛛"],"identification":"主要危害叶片和果实。受害果面可出现灰尘般黄褐色粉状物，后果皮颜色和质地发生变化、表面粗糙；叶片受害可失绿。田间虫体微小，需结合放大观察和果面症状判断。","symptomKeywords":["锈壁虱","锈蜘蛛","灰尘状黄褐色粉状物","黄褐色粉状物","果皮褐化","果皮粗糙","叶片失绿"]}' AS JSON);
