-- 病斑图片样本库：只保存已审核样本的元数据与视觉指纹，图片文件通过受保护的图片资源地址访问。
CREATE TABLE IF NOT EXISTS agri_prod_pest_image_sample (
 id VARCHAR(36) NOT NULL PRIMARY KEY,
 atlas_id VARCHAR(36) NOT NULL,
 atlas_revision INT NOT NULL,
 sample_revision INT NOT NULL DEFAULT 1,
 crop_name VARCHAR(100) NOT NULL,
 disease_name VARCHAR(200) NOT NULL,
 image_url VARCHAR(500) NOT NULL,
 image_sha256 CHAR(64) NOT NULL,
 image_phash CHAR(16) NOT NULL,
 width INT NOT NULL,
 height INT NOT NULL,
 source VARCHAR(500) NOT NULL,
 source_version VARCHAR(200) NOT NULL,
 source_ref VARCHAR(500) NOT NULL,
 note VARCHAR(1000),
 status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',
 created_by VARCHAR(100) NOT NULL,
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 published_at DATETIME NULL,
 UNIQUE KEY uk_pest_image_hash(image_sha256),
 KEY idx_pest_image_scope(atlas_id,atlas_revision,status),
 KEY idx_pest_image_crop(crop_name,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS agri_prod_pest_image_revision (
 id VARCHAR(36) NOT NULL,
 revision INT NOT NULL,
 status VARCHAR(16) NOT NULL,
 payload_json JSON NOT NULL,
 recorded_at DATETIME NOT NULL,
 PRIMARY KEY(id,revision)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 病例图片检索证据快照：每次诊断尝试独立留痕，不随样本库更新而变化。
CREATE TABLE IF NOT EXISTS agri_prod_pest_image_snapshot (
 case_id VARCHAR(36) NOT NULL,
 attempt_id VARCHAR(36) NOT NULL,
 tenant_id VARCHAR(191) NOT NULL,
 snapshot_json JSON NOT NULL,
 created_at DATETIME NOT NULL,
 PRIMARY KEY(case_id, attempt_id),
 INDEX idx_pest_image_snapshot_tenant(tenant_id, case_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
